import React, {Component, ErrorInfo, ReactNode} from 'react';
import {
  View,
  TouchableOpacity,
  ScrollView,
  StyleSheet,
} from 'react-native';
import {AppText} from '../components/core/AppText/AppText';
import {logger} from '../lib/logger';

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface FallbackColors {
  background: string;
  text: string;
  textSecondary: string;
  accent: string;
  border: string;
  accentDim: string;
}

interface ErrorBoundaryProps {
  children: ReactNode;
  fallbackColors: FallbackColors;
  /** Called when user taps "Go Back" ΓÇö navigates away from the errored screen */
  onGoBack?: () => void;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
  showDetails: boolean;
}

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export class ErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      showDetails: false,
    };
  }

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return {hasError: true, error};
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    this.setState({errorInfo});
    logger.error('[ErrorBoundary]', error, errorInfo);
  }

  handleRetry = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      showDetails: false,
    });
  };

  toggleDetails = () => {
    this.setState(prev => ({showDetails: !prev.showDetails}));
  };

  render() {
    if (this.state.hasError) {
      const {background, text, textSecondary, accent, border, accentDim} =
        this.props.fallbackColors;

      return (
        <View style={[styles.container, {backgroundColor: background}]}>
          {/* Icon */}
          <View style={[styles.iconContainer, {backgroundColor: accentDim}]}>
            <AppText
              style={[styles.iconText, {color: accent}]}
              variant="h1">
              !
            </AppText>
          </View>

          {/* Message */}
          <AppText variant="h2" style={[styles.title, {color: text}]}>
            Something went wrong
          </AppText>
          <AppText
            variant="body2"
            style={[styles.message, {color: textSecondary}]}>
            An unexpected error has occurred. Please try again or restart the
            app.
          </AppText>

          {/* Retry button */}
          <TouchableOpacity
            style={[styles.retryButton, {backgroundColor: accent}]}
            onPress={this.handleRetry}
            accessibilityRole="button"
            accessibilityLabel="Try Again">
            <AppText
              variant="body2"
              style={[styles.retryText, {color: background}]}>
              Try Again
            </AppText>
          </TouchableOpacity>

          {/* Go Back button */}
          {this.props.onGoBack && (
            <TouchableOpacity
              style={[styles.goBackButton, {borderColor: border}]}
              onPress={this.props.onGoBack}
              accessibilityRole="button"
              accessibilityLabel="Go Back">
              <AppText variant="body2" style={[{color: textSecondary}]}>
                Go Back
              </AppText>
            </TouchableOpacity>
          )}

          {/* Error details toggle */}
          {this.state.error && (
            <TouchableOpacity
              onPress={this.toggleDetails}
              style={styles.detailsToggle}
              accessibilityRole="button"
              accessibilityLabel={
                this.state.showDetails
                  ? 'Hide error details'
                  : 'Show error details'
              }>
              <AppText
                variant="caption"
                style={[{color: textSecondary}]}>
                {this.state.showDetails ? 'Hide Details' : 'Show Details'}
              </AppText>
            </TouchableOpacity>
          )}

          {/* Collapsible details */}
          {this.state.showDetails && this.state.error && (
            <ScrollView
              style={[
                styles.detailsContainer,
                {backgroundColor: border + '15', borderColor: border},
              ]}
              nestedScrollEnabled>
              <AppText variant="mono" style={[styles.detailText, {color: textSecondary}]}>
                {this.state.error.toString()}
              </AppText>
              {this.state.errorInfo && (
                <AppText
                  variant="mono"
                  style={[
                    styles.detailText,
                    {color: textSecondary, marginTop: 8},
                  ]}>
                  {this.state.errorInfo.componentStack}
                </AppText>
              )}
            </ScrollView>
          )}
        </View>
      );
    }

    return this.props.children;
  }
}

// ΓöÇΓöÇΓöÇ Styles ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const styles = StyleSheet.create({
  container: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 32,
  },
  iconContainer: {
    width: 80,
    height: 80,
    borderRadius: 40,
    alignItems: 'center',
    justifyContent: 'center',
    marginBottom: 24,
  },
  iconText: {
    fontWeight: '700',
    fontSize: 36,
  },
  title: {
    marginBottom: 8,
    textAlign: 'center',
  },
  message: {
    textAlign: 'center',
    marginBottom: 32,
    lineHeight: 22,
    paddingHorizontal: 16,
  },
  retryButton: {
    paddingHorizontal: 32,
    paddingVertical: 14,
    borderRadius: 12,
    marginBottom: 20,
    minWidth: 160,
    alignItems: 'center',
  },
  retryText: {
    fontWeight: '600',
  },
  goBackButton: {
    paddingHorizontal: 32,
    paddingVertical: 12,
    borderRadius: 12,
    borderWidth: 1,
    minWidth: 160,
    alignItems: 'center',
    marginBottom: 20,
  },
  detailsToggle: {
    paddingVertical: 8,
  },
  detailsContainer: {
    marginTop: 12,
    padding: 12,
    borderWidth: 1,
    borderRadius: 8,
    maxHeight: 200,
    width: '100%',
  },
  detailText: {
    fontSize: 11,
    lineHeight: 16,
  },
});

import React, {useState, useCallback} from 'react';
import {
  View,
  TouchableOpacity,
  StyleSheet,
} from 'react-native';
import {useTheme} from '../../theme';
import {spacing, radius} from '../../theme/tokens';
import {AppText} from '../core/AppText/AppText';
import {AppTextInput} from '../core/AppTextInput/AppTextInput';
import {KeyboardAwareView} from '../core/KeyboardAwareView/KeyboardAwareView';
import {SvgIcon} from '../utility/SvgIcon';
import {BookmarkItem} from './BookmarkItem';
import {BottomSheet} from '../sheets/BottomSheet/BottomSheet';
import type {Bookmark} from '../../store/slices/bookmarkSlice';

interface Props {
  visible: boolean;
  onClose: () => void;
  currentPosition: number;
  duration: number;
  fileUri: string;
  fileTitle: string;
  mediaType: 'video' | 'audio';
  thumbnailPath?: string;
  bookmarks: Bookmark[];
  onSave: (label: string) => void;
  onDelete: (id: string) => void;
  onJumpTo: (position: number) => void;
}

function formatTime(seconds: number): string {
  if (!isFinite(seconds) || seconds < 0) return '0:00';
  const minutes = Math.floor(seconds / 60);
  const secs = Math.floor(seconds % 60)
    .toString()
    .padStart(2, '0');
  return `${minutes}:${secs}`;
}

export const BookmarkSheet: React.FC<Props> = ({
  visible,
  onClose,
  currentPosition,
  duration,
  bookmarks,
  onSave,
  onDelete,
  onJumpTo,
}) => {
  const {colors} = useTheme();
  const [label, setLabel] = useState('');

  const handleSave = useCallback(() => {
    if (currentPosition < 1) return;
    onSave(label);
    setLabel('');
    onClose();
  }, [currentPosition, label, onSave, onClose]);

  const handleJumpTo = useCallback(
    (item: Bookmark) => {
      onJumpTo(item.position);
      onClose();
    },
    [onJumpTo, onClose],
  );

  const handleDelete = useCallback(
    (id: string) => {
      onDelete(id);
    },
    [onDelete],
  );

  const canSave = currentPosition >= 1;

  return (
    <BottomSheet
      visible={visible}
      onClose={onClose}
      snapPoints={['40%', '65%']}
      initialSnap={0}
      title={
        <View style={styles.titleRow}>
          <SvgIcon name="bookmark" size={20} color={colors.accent.gold} />
          <AppText variant="h3" color="primary" style={{marginLeft: spacing.sm}}>
            Bookmarks
          </AppText>
        </View>
      }>
      <KeyboardAwareView style={styles.container}>
        {/* ΓöÇΓöÇ Save new bookmark ΓöÇΓöÇ */}
        <View
          style={[
            styles.saveSection,
            {borderBottomColor: colors.border.subtle},
          ]}>
          {/* Position info */}
          {canSave && (
            <AppText variant="caption" color="secondary" style={styles.positionInfo}>
              Current position: {formatTime(currentPosition)}
              {duration > 0 ? ` / ${formatTime(duration)}` : ''}
            </AppText>
          )}

          {/* Input + Save button */}
          <View style={styles.saveRow}>
            <AppTextInput
              value={label}
              onChangeText={setLabel}
              placeholder="Label (optional)"
              label="Label"
              clearable
              containerStyle={styles.inputWrap}
              accessibilityLabel="Bookmark label"
            />
            <TouchableOpacity
              style={[
                styles.saveBtn,
                {
                  backgroundColor: canSave
                    ? colors.accent.gold
                    : colors.text.tertiary,
                },
              ]}
              onPress={handleSave}
              disabled={!canSave}
              activeOpacity={0.7}
              accessibilityRole="button"
              accessibilityLabel="Save bookmark">
              <SvgIcon name="bookmark" size={18} color={colors.text.inverse} />
              <AppText
                variant="button"
                style={{color: colors.text.inverse, marginLeft: 4}}>
                Save
              </AppText>
            </TouchableOpacity>
          </View>
        </View>

        {/* ΓöÇΓöÇ Existing bookmarks list ΓöÇΓöÇ */}
        <View style={styles.listSection}>
          {bookmarks.length === 0 ? (
            <View style={styles.empty}>
              <SvgIcon
                name="bookmark"
                size={32}
                color={colors.text.tertiary}
              />
              <AppText variant="body2" color="tertiary" style={{marginTop: spacing.sm}}>
                No bookmarks yet. Save your current position to start.
              </AppText>
            </View>
          ) : (
            <View>
              {bookmarks.map(item => (
                <BookmarkItem
                  key={item.id}
                  item={item}
                  onPress={handleJumpTo}
                  onDelete={handleDelete}
                />
              ))}
            </View>
          )}
        </View>
      </KeyboardAwareView>
    </BottomSheet>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
  titleRow: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  saveSection: {
    padding: spacing.md,
    borderBottomWidth: 1,
  },
  positionInfo: {
    marginBottom: spacing.sm,
  },
  saveRow: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: spacing.sm,
  },
  inputWrap: {
    flex: 1,
  },
  saveBtn: {
    flexDirection: 'row',
    alignItems: 'center',
    paddingVertical: 10,
    paddingHorizontal: spacing.lg,
    borderRadius: radius.sm,
  },
  listSection: {
    flex: 1,
  },
  empty: {
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: spacing.xxl * 2,
  },
});

