import React, {useMemo, useRef, useCallback} from 'react';
import {
  TouchableOpacity,
  StyleSheet,
  View,
  ViewStyle,
  TextStyle,
  Animated,
} from 'react-native';
import {useTheme} from '../../../theme';
import {radius, spacing} from '../../../theme/tokens';
import {AppText} from '../AppText/AppText';
import {ActivityOrb} from '../../feedback/ActivityOrb/ActivityOrb';
import {useHaptics} from '../../../hooks/useHaptics';

type ButtonVariant = 'primary' | 'secondary' | 'outline' | 'text';
type ButtonSize = 'sm' | 'md' | 'lg';

interface AppButtonProps {
  title: string;
  onPress: () => void;
  variant?: ButtonVariant;
  size?: ButtonSize;
  loading?: boolean;
  disabled?: boolean;
  fullWidth?: boolean;
  icon?: React.ReactNode;
  iconPosition?: 'left' | 'right';
  hint?: string;
  style?: ViewStyle;
  textStyle?: TextStyle;
}

const sizeConfig: Record<ButtonSize, {px: number; py: number; fs: number; minH: number}> = {
  sm: {px: spacing.lg, py: spacing.sm, fs: 13, minH: 36},
  md: {px: spacing.xl, py: spacing.md, fs: 15, minH: 44},
  lg: {px: spacing.xxl, py: spacing.lg, fs: 17, minH: 52},
};

export const AppButton: React.FC<AppButtonProps> = ({
  title,
  onPress,
  variant = 'primary',
  size: sizeKey = 'md',
  loading = false,
  disabled = false,
  fullWidth = false,
  icon,
  iconPosition = 'left',
  hint,
  style,
  textStyle,
}) => {
  const {colors} = useTheme();
  const {medium: hapticMedium} = useHaptics();
  const scaleAnim = useRef(new Animated.Value(1)).current;
  const sz = sizeConfig[sizeKey];

  const handlePressIn = useCallback(() => {
    hapticMedium();
    Animated.spring(scaleAnim, {toValue: 0.95, friction: 8, tension: 100, useNativeDriver: true}).start();
  }, [scaleAnim, hapticMedium]);

  const handlePressOut = useCallback(() => {
    Animated.spring(scaleAnim, {toValue: 1, friction: 3, tension: 200, useNativeDriver: true}).start();
  }, [scaleAnim]);

  const {bgColor, txtColor, bdColor} = useMemo(() => {
    if (disabled) {
      return {
        bgColor: colors.border.subtle,
        txtColor: colors.text.tertiary,
        bdColor: 'transparent',
      };
    }
    switch (variant) {
      case 'primary':
        return {
          bgColor: colors.accent.gold,
          txtColor: colors.text.primary,
          bdColor: 'transparent',
        };
      case 'secondary':
        return {
          bgColor: colors.accent.goldDim,
          txtColor: colors.accent.gold,
          bdColor: 'transparent',
        };
      case 'outline':
        return {
          bgColor: 'transparent',
          txtColor: colors.accent.gold,
          bdColor: colors.accent.gold,
        };
      case 'text':
        return {
          bgColor: 'transparent',
          txtColor: colors.accent.gold,
          bdColor: 'transparent',
        };
    }
  }, [disabled, colors, variant]);

  return (
    <Animated.View style={[{transform: [{scale: scaleAnim}]}]}>
      <TouchableOpacity
        style={[
          styles.base,
          {
            backgroundColor: bgColor,
            borderColor: bdColor,
            borderWidth: variant === 'outline' ? 1 : 0,
            paddingHorizontal: sz.px,
            paddingVertical: sz.py,
            minHeight: sz.minH,
            alignSelf: fullWidth ? 'stretch' : undefined,
            opacity: disabled ? 0.5 : 1,
          },
          style,
        ]}
        onPress={onPress}
        onPressIn={handlePressIn}
        onPressOut={handlePressOut}
        disabled={disabled || loading}
        activeOpacity={0.7}
        accessibilityRole="button"
        accessibilityState={{disabled: disabled || loading}}
        accessibilityLabel={loading ? `${title}, loading` : title}
        accessibilityHint={hint}>
        {loading ? (
          <ActivityOrb size={16} color={txtColor} />
        ) : (
          <View style={[styles.inner, {flexDirection: iconPosition === 'right' ? 'row-reverse' : 'row'}]}>
            {icon && <View style={styles.iconSlot}>{icon}</View>}
            <AppText
              variant="button"
              style={[
                {
                  color: txtColor,
                  fontSize: sz.fs,
                  fontWeight: '600',
                },
                textStyle,
              ]}
              numberOfLines={1}>
              {title}
            </AppText>
          </View>
        )}
      </TouchableOpacity>
    </Animated.View>
  );
};

const styles = StyleSheet.create({
  base: {
    borderRadius: radius.md,
    alignItems: 'center',
    justifyContent: 'center',
  },
  inner: {
    alignItems: 'center',
    justifyContent: 'center',
    gap: spacing.sm,
  },
  iconSlot: {},
});

import React from 'react';
import {View} from 'react-native';
import {useTheme} from '../../../theme';
import {AppText} from '../AppText/AppText';
import {SvgIcon} from '../../utility/SvgIcon/SvgIcon';

export interface AvatarProps {
  uri?: string | null;
  name?: string;
  size?: number;
}

/**
 * User avatar ΓÇö shows image when available, otherwise falls back to
 * initials or a generic person icon.
 */
export const Avatar: React.FC<AvatarProps> = ({
  uri,
  name,
  size = 40,
}) => {
  const {colors} = useTheme();
  const initials = name
    ? name
        .split(' ')
        .map(w => w[0])
        .join('')
        .toUpperCase()
        .slice(0, 2)
    : '';

  const fontSize = size * 0.38;

  if (uri) {
    return (
      <View
        style={{
          width: size,
          height: size,
          borderRadius: size / 2,
          overflow: 'hidden',
          backgroundColor: colors.background.highlight,
        }}>
        {/* Inline <Image> would go here with FastImage for production.
            For now we render a fallback until image URL is available. */}
        <View
          style={{
            flex: 1,
            alignItems: 'center',
            justifyContent: 'center',
          }}>
          <AppText
            style={{fontSize, fontWeight: '600', color: colors.text.primary}}>
            {initials}
          </AppText>
        </View>
      </View>
    );
  }

  // Fallback: initials or icon
  return (
    <View
      style={{
        width: size,
        height: size,
        borderRadius: size / 2,
        alignItems: 'center',
        justifyContent: 'center',
        backgroundColor: colors.border.subtle,
      }}>
      {initials ? (
        <AppText
          style={{fontSize, fontWeight: '600', color: colors.text.secondary}}>
          {initials}
        </AppText>
      ) : (
        <SvgIcon name="music" size={size * 0.5} color={colors.text.tertiary} />
      )}
    </View>
  );
};

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Simba Player ΓÇö Base Dialog Component
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Phase 14: Professional modal dialog with backdrop,
// title, content, and action buttons.

import React, {useEffect, useRef} from 'react';
import {
  View,
  Modal,
  TouchableOpacity,
  StyleSheet,
  Animated,
  TextStyle,
} from 'react-native';
import {useTheme} from '../../../theme';
import {ColorTokens} from '../../../theme/tokens';
import {useHaptics} from '../../../hooks/useHaptics';
import {AppText} from '../AppText/AppText';
import {KeyboardAwareView} from '../KeyboardAwareView/KeyboardAwareView';

export interface DialogAction {
  label: string;
  onPress: () => void;
  variant?: 'default' | 'primary' | 'destructive';
  disabled?: boolean;
}

interface DialogProps {
  visible: boolean;
  onClose: () => void;
  title: string;
  message?: string;
  children?: React.ReactNode;
  actions?: DialogAction[];
  /** If true, tapping backdrop dismisses dialog */
  dismissable?: boolean;
}

export const Dialog: React.FC<DialogProps> = ({
  visible,
  onClose,
  title,
  message,
  children,
  actions,
  dismissable = true,
}) => {
  const {colors, radius: r} = useTheme();
  const haptics = useHaptics();
  const fadeAnim = useRef(new Animated.Value(0)).current;
  const scaleAnim = useRef(new Animated.Value(0.92)).current;
  // 52.7: focus lands on the first action when the dialog opens
  const firstActionRef = useRef<React.ElementRef<typeof TouchableOpacity> | null>(null);

  useEffect(() => {
    if (visible) {
      Animated.parallel([
        Animated.timing(fadeAnim, {
          toValue: 1,
          duration: 200,
          useNativeDriver: true,
        }),
        Animated.spring(scaleAnim, {
          toValue: 1,
          damping: 20,
          stiffness: 260,
          mass: 0.5,
          useNativeDriver: true,
        }),
      ]).start();
    } else {
      fadeAnim.setValue(0);
      scaleAnim.setValue(0.92);
    }
  }, [visible, fadeAnim, scaleAnim]);

  const handleBackdropPress = () => {
    if (dismissable) onClose();
  };

  return (
    <Modal
      visible={visible}
      transparent
      animationType="none"
      statusBarTranslucent
      onRequestClose={onClose}
      accessibilityViewIsModal
      onShow={() => {
        // 52.7: move screen-reader / key focus to the primary action
        firstActionRef.current?.focus();
      }}>
      <KeyboardAwareView style={styles.overlay}>
        {/* Animated scrim */}
        <Animated.View
          style={[
            StyleSheet.absoluteFill,
            {
              backgroundColor: colors.background.overlay,
              opacity: fadeAnim,
            },
          ]}
        />

        {/* Backdrop touchable */}
        <TouchableOpacity
          style={StyleSheet.absoluteFill}
          activeOpacity={1}
          onPress={handleBackdropPress}
        />

        {/* Dialog card */}
        <Animated.View
          style={[
            styles.card,
            {
              backgroundColor: colors.background.floating,
              borderColor: colors.border.subtle,
              borderRadius: r.lg,
              opacity: fadeAnim,
              transform: [{scale: scaleAnim}],
              shadowOffset: {width: 0, height: 8},
              shadowOpacity: 0.4,
              shadowRadius: 24,
              elevation: 16,
            },
          ]}
          accessibilityRole="alert"
          accessibilityLiveRegion="polite"
          importantForAccessibility="yes">
          {/* Title */}
          <AppText variant="h3" color="primary" style={styles.title}>
            {title}
          </AppText>

          {/* Message */}
          {message && (
            <AppText variant="body2" color="secondary" style={styles.message}>
              {message}
            </AppText>
          )}

          {/* Custom children */}
          {children}

          {/* Action buttons */}
          {actions && actions.length > 0 && (
            <View
              style={[
                styles.actions,
                actions.length === 2 && styles.actionsDouble,
              ]}>
              {actions.map((action, i) => (
                <TouchableOpacity
                  key={i}
                  ref={i === 0 ? firstActionRef : undefined}
                  style={[
                    styles.actionBtn,
                    action.variant !== 'default' && action.variant !== undefined
                      ? getActionStyle(action.variant, colors)
                      : styles.actionBtnDefault,
                    action.disabled && styles.actionDisabled,
                  ]}
                  activeOpacity={0.7}
                  disabled={action.disabled}
                  accessibilityHint={action.label}
                  onPress={() => {
                    if (action.variant === 'destructive') {
                      haptics.heavy();
                    }
                    action.onPress();
                  }}>
                  <AppText
                    variant="button"
                    color={
                      action.variant === 'destructive'
                        ? 'error'
                        : action.variant === 'primary'
                        ? 'primary'
                        : 'accent'
                    }
                    style={action.disabled ? {opacity: 0.4} : undefined}>
                    {action.label}
                  </AppText>
                </TouchableOpacity>
              ))}
            </View>
          )}
        </Animated.View>
      </KeyboardAwareView>
    </Modal>
  );
};

function getActionStyle(
  variant: 'default' | 'primary' | 'destructive',
  colors: ColorTokens,
): TextStyle {
  switch (variant) {
    case 'primary':
      return {
        backgroundColor: colors.accent.gold,
        borderWidth: 0,
      } as any;
    case 'destructive':
      return {
        backgroundColor: colors.semantic.error + '1F', // ~12% opacity
        borderWidth: 1,
        borderColor: colors.semantic.error + '4D', // ~30% opacity
      } as any;
    default:
      return {};
  }
}

