          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'space-between',
          height: HEADER_HEIGHT,
          paddingHorizontal: spacing.lg,
          borderBottomWidth: StyleSheet.hairlineWidth,
          borderBottomColor: colors.border.subtle,
        },
        headerTitle: {
          fontSize: 17,
          fontWeight: '600',
        },
        closeBtn: {
          width: 32,
          height: 32,
          borderRadius: 16,
          alignItems: 'center',
          justifyContent: 'center',
          backgroundColor: colors.background.highlight,
        },
        // ΓöÇΓöÇ Toggle Tabs (15.9) ΓöÇΓöÇ
        tabRow: {
          flexDirection: 'row',
          paddingHorizontal: spacing.xl,
          paddingVertical: spacing.md,
          gap: spacing.sm,
        },
        tabBtn: {
          paddingHorizontal: spacing.xl,
          paddingVertical: spacing.sm,
          borderRadius: 20,
        },
        tabBtnActive: {
          backgroundColor: colors.border.emphasis,
        },
        tabBtnInactive: {
          backgroundColor: 'transparent',
        },
        tabLabel: {
          fontSize: 14,
          fontWeight: '500',
        },
        // ΓöÇΓöÇ Lyrics content ΓöÇΓöÇ
        lyricsContainer: {
          flex: 1,
        },
        lyricsList: {
          flex: 1,
          paddingHorizontal: spacing.xxl,
        },
        lyricRow: {
          paddingVertical: spacing.sm,
          paddingHorizontal: spacing.sm,
          borderRadius: 8,
        },
        activeLyricRow: {
          paddingVertical: spacing.sm,
          paddingHorizontal: spacing.sm,
          borderRadius: 8,
        },
        lyricText: {
          fontSize: 16,
          lineHeight: 24,
          color: colors.text.secondary,
        },
        activeLyricText: {
          fontSize: 18,
          fontWeight: '700',
          color: colors.text.bright, // bright white over artwork (15.6)
        },
        // ΓöÇΓöÇ No lyrics empty state (15.10) ΓöÇΓöÇ
        noLyricsContainer: {
          flex: 1,
          justifyContent: 'center',
          alignItems: 'center',
          paddingBottom: 60,
        },
        noLyricsIconWrap: {
          width: 64,
          height: 64,
          borderRadius: 32,
          backgroundColor: colors.border.subtle,
          alignItems: 'center',
          justifyContent: 'center',
          marginBottom: spacing.lg,
        },
        noLyricsText: {
          fontSize: 15,
          color: colors.text.secondary,
          marginTop: 8,
        },
        // ΓöÇΓöÇ Queue section ΓöÇΓöÇ
        queueContainer: {
          flex: 1,
          paddingHorizontal: 24,
          paddingTop: 8,
        },
        queueItemRow: {
          flexDirection: 'row',
          alignItems: 'center',
          paddingVertical: 12,
          paddingHorizontal: 12,
          borderRadius: 10,
          marginBottom: 4,
        },
        queueItemActive: {
          backgroundColor: colors.accent.goldDim,
        },
        queueIndex: {
          width: 28,
          textAlign: 'center',
          marginRight: 12,
        },
        queueTitle: {
          flex: 1,
        },
        queueActiveDot: {
          width: 6,
          height: 6,
          borderRadius: 3,
          backgroundColor: colors.accent.gold,
          marginRight: 8,
        },
        queueSeparator: {
          height: StyleSheet.hairlineWidth,
          backgroundColor: colors.border.subtle,
        },
      }),
    [colors, insets],
  );

  // ΓöÇΓöÇ Render lyric item ΓöÇΓöÇ
  const renderLyricItem = useCallback(
    ({item, index}: {item: LrcLine; index: number}) => {
      const isActive = index === activeIndex;

      if (isActive) {
        return (
          <TouchableOpacity
            onPress={() => onSeekToLyric?.(item.time)}
            activeOpacity={0.7}>
            <Animated.View
              style={[
                styles.activeLyricRow,
                {
                  backgroundColor: isPlaying
                    ? colors.background.highlight
                    : colors.background.highlightDim,
                },
              ]}>
              <AppText style={styles.activeLyricText}>{item.text}</AppText>
            </Animated.View>
          </TouchableOpacity>
        );
      }

      return (
        <TouchableOpacity
          onPress={() => onSeekToLyric?.(item.time)}
          activeOpacity={0.7}
          style={styles.lyricRow}>
          <AppText style={styles.lyricText}>{item.text}</AppText>
        </TouchableOpacity>
      );
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [activeIndex, styles, onSeekToLyric, isPlaying],
  );

  // ΓöÇΓöÇ Key extractor ΓöÇΓöÇ
  const keyExtractor = useCallback(
    (item: LrcLine, index: number) => `${item.time}-${index}`,
    [],
  );

  if (!visible) return null;

  return (
    <Animated.View
      style={[
        styles.overlay,
        {
          opacity: overlayOpacity,
          transform: [{translateY: overlayTranslateY}],
        },
      ]}>
      <View style={styles.container}>
        {/* ΓöÇΓöÇ Header ΓöÇΓöÇ */}
