          <TouchableOpacity
            style={[styles.tabBtn, activeTab === 'queue' ? styles.tabBtnActive : styles.tabBtnInactive]}
            onPress={() => setActiveTab('queue')}
            activeOpacity={0.7}>
            <AppText
              variant="body2"
              style={[styles.tabLabel, {color: activeTab === 'queue' ? colors.text.bright : colors.text.secondary}]}>
              Queue
            </AppText>
          </TouchableOpacity>
        </View>

        {/* ΓöÇΓöÇ Content ΓöÇΓöÇ */}
        {activeTab === 'lyrics' ? (
          lyrics.length === 0 ? (
            /* ΓöÇΓöÇ No Lyrics Empty State (15.10) ΓöÇΓöÇ */
            <View style={styles.noLyricsContainer}>
              <Animated.View
                style={[
                  styles.noLyricsIconWrap,
                  {
                    transform: [
                      {
                        translateY: noteAnim.interpolate({
                          inputRange: [0, 1],
                          outputRange: [0, -6],
                        }),
                      },
                    ],
                  },
                ]}>
                <SvgIcon name="music" size={28} color={colors.text.tertiary} />
              </Animated.View>
              <AppText variant="body1" color="secondary" style={styles.noLyricsText}>
                No lyrics available
              </AppText>
            </View>
          ) : (
            /* ΓöÇΓöÇ Lyrics List ΓöÇΓöÇ */
            <View style={styles.lyricsContainer}>
              <FlatList
                ref={flatListRef}
                data={lyrics}
                renderItem={renderLyricItem}
                keyExtractor={keyExtractor}
                showsVerticalScrollIndicator={false}
                contentContainerStyle={{paddingVertical: 16, paddingBottom: 60}}
                getItemLayout={(_data, index) => ({
                  length: ESTIMATED_LINE_HEIGHT,
                  offset: ESTIMATED_LINE_HEIGHT * index,
                  index,
                })}
                windowSize={7}
                maxToRenderPerBatch={15}
                removeClippedSubviews={true}
              />
            </View>
          )
        ) : (
          /* ΓöÇΓöÇ Queue Tab ΓöÇΓöÇ */
          <View style={styles.queueContainer}>
            {queue.length === 0 ? (
              <View style={styles.noLyricsContainer}>
                <AppText variant="body1" color="secondary">
                  Queue is empty
                </AppText>
              </View>
            ) : (
              <FlatList
                data={queue}
                keyExtractor={(item, index) => `queue-${index}-${item.uri}`}
                showsVerticalScrollIndicator={false}
                contentContainerStyle={{paddingBottom: 60}}
                renderItem={({item, index}) => {
                  const isActive = index === currentIndex;
                  if (index < (currentIndex ?? -1) + 1) return null;
                  return (
                    <TouchableOpacity
                      style={[
                        styles.queueItemRow,
                        isActive && styles.queueItemActive,
                      ]}
                      onPress={() => onPlayFromQueue?.(index)}
                      activeOpacity={0.7}>
                      <AppText
                        variant="caption"
                        color="secondary"
                        style={styles.queueIndex}>
                        {index + 1}
                      </AppText>
                      {isActive && <View style={styles.queueActiveDot} />}
                      <AppText
                        variant="body2"
                        color="primary"
                        numberOfLines={1}
                        style={styles.queueTitle}>
                        {item.title}
                      </AppText>
                    </TouchableOpacity>
                  );
                }}
              />
            )}
          </View>
        )}
      </View>
    </Animated.View>
  );
};

