import React, {useRef, useState, useCallback, useMemo} from 'react';
import {
  View,
  PanResponder,
  Animated,
  StyleSheet,
  Platform,
  LayoutChangeEvent,
} from 'react-native';
import {AppText} from '../../core/AppText/AppText';
import {useTheme} from '../../../theme';

// ΓöÇΓöÇΓöÇ Static styles for VolumeIcon ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
const iconStyles = StyleSheet.create({
  volIconRow: {
    flexDirection: 'row',
    alignItems: 'center',
    width: 32,
    height: 24,
  },
  speakerBody: {
    width: 10,
    height: 14,
    borderWidth: 2,
    borderRadius: 2,
    borderRightWidth: 0,
    backgroundColor: 'transparent',
  },
  speakerCone: {
    width: 6,
    height: 10,
    borderTopRightRadius: 3,
    borderBottomRightRadius: 3,
  },
  waveRow: {
    flexDirection: 'row',
    alignItems: 'center',
    marginLeft: 2,
    gap: 2,
  },
  waveBar: {
    width: 3,
    borderRadius: 1.5,
  },
});

interface AudioVolumeSliderProps {
  volume: number;
  onVolumeChange: (delta: number) => void;
}

/**
 * * * * Volume icon bar chunks ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */
const VolumeIcon: React.FC<{level: number; color: string}> = ({level, color}) => {
  const barCount = 3;
  const activeBars =
    level === 0 ? 0
    : level <= 33 ? 1
    : level <= 66 ? 2
    : 3;

  return (
    <View style={iconStyles.volIconRow}>
      {/* Speaker body */}
      <View style={[iconStyles.speakerBody, {borderColor: color}]} />
      <View style={[iconStyles.speakerCone, {backgroundColor: color}]} />

      {/* Sound wave bars */}
      {level > 0 && (
        <View style={iconStyles.waveRow}>
          {Array.from({length: barCount}).map((_, i) => (
            <View
              key={i}
              style={[
                iconStyles.waveBar,
                {
                  backgroundColor: i < activeBars ? color : 'transparent',
                  borderColor: color,
                  borderWidth: i >= activeBars ? 1 : 0,
                  height: 10 + i * 4,
                },
              ]}
            />
          ))}
        </View>
      )}
    </View>
  );
};

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export const AudioVolumeSlider: React.FC<AudioVolumeSliderProps> = ({
  volume,
  onVolumeChange,
}) => {
  const {colors} = useTheme();

  const trackWidthRef = useRef(1);
  const [isDragging, setIsDragging] = useState(false);
  const [dragFraction, setDragFraction] = useState(0);
  const dragFractionRef = useRef(0);

  const thumbScale = useRef(new Animated.Value(1)).current;

  const volumeFraction = volume / 100;
  const displayFraction = isDragging ? dragFraction : volumeFraction;

  // Haptic at extremes
  const triggerHaptic = useCallback(() => {
    if (Platform.OS === 'ios' || Platform.OS === 'android') {
      try {
        const RNHaptics = require('react-native-haptic-feedback');
        RNHaptics.default.trigger('impactMedium', {
          enableVibrateFallback: true,
          ignoreAndroidSystemSettings: false,
        });
      } catch {}
    }
  }, []);

  const panResponder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onMoveShouldSetPanResponder: () => true,

        onPanResponderGrant: (evt) => {
          const x = evt.nativeEvent.locationX;
          const frac = Math.max(0, Math.min(1, x / Math.max(trackWidthRef.current, 1)));
          setDragFraction(frac);
          dragFractionRef.current = frac;
          setIsDragging(true);
          Animated.spring(thumbScale, {
            toValue: 1.3,
            useNativeDriver: true,
            friction: 6,
            tension: 120,
          }).start();
        },

        onPanResponderMove: (evt) => {
          const x = evt.nativeEvent.locationX;
          const frac = Math.max(0, Math.min(1, x / Math.max(trackWidthRef.current, 1)));
          setDragFraction(frac);
          dragFractionRef.current = frac;
        },

        onPanResponderRelease: () => {
          const frac = dragFractionRef.current;
          setIsDragging(false);
          Animated.spring(thumbScale, {
            toValue: 1,
            useNativeDriver: true,
            friction: 4,
            tension: 100,
          }).start();

          // Convert fraction to delta from current volume
          const targetVol = Math.round(frac * 100);
          const currentVol = volume;
          const delta = targetVol - currentVol;
          onVolumeChange(delta);

          // Haptic at extremes
          if (targetVol === 0 || targetVol === 100) {
            triggerHaptic();
          }
        },

        onPanResponderTerminate: () => {
          setIsDragging(false);
          Animated.spring(thumbScale, {
            toValue: 1,
            useNativeDriver: true,
            friction: 4,
            tension: 100,
          }).start();
        },
      }),
    [onVolumeChange, volume, thumbScale, triggerHaptic],
  );

  const handleTrackLayout = useCallback((e: LayoutChangeEvent) => {
    trackWidthRef.current = e.nativeEvent.layout.width;
  }, []);

  const styles = useMemo(
    () =>
      StyleSheet.create({
        container: {
          flexDirection: 'row',
          alignItems: 'center',
          gap: 8,
          paddingHorizontal: 16,
          marginBottom: 16,
        },
        trackContainer: {
          flex: 1,
          height: 24,
          justifyContent: 'center',
          position: 'relative',
        },
        trackBg: {
          height: 4,
          borderRadius: 4,
          backgroundColor: colors.text.tertiary,
        },
        trackFill: {
          position: 'absolute',
          left: 0,
          top: 10,
          height: 4,
          borderRadius: 4,
          backgroundColor: colors.accent.gold,
        },
        thumb: {
          position: 'absolute',
          width: 16,
          height: 16,
          borderRadius: 8,
          backgroundColor: colors.text.bright,
          borderWidth: 2,
          borderColor: colors.accent.gold,
          top: 4,
          marginLeft: -8,
          // Shadow
          elevation: 4,
          shadowColor: colors.shadow,
          shadowOffset: {width: 0, height: 2},
          shadowOpacity: 0.3,
          shadowRadius: 4,
        },
        pctLabel: {
          minWidth: 36,
          textAlign: 'right',
        },

      }),
    [colors],
  );

  return (
    <View style={styles.container}>
      {/* Volume icon */}
      <VolumeIcon level={displayFraction * 100} color={colors.text.primary} />

      {/* Slider track */}
      <View
        style={styles.trackContainer}
        onLayout={handleTrackLayout}
        accessibilityRole="adjustable"
        accessibilityLabel={`Volume, ${Math.round(displayFraction * 100)} percent`}
        accessibilityValue={{min: 0, max: 100, now: Math.round(displayFraction * 100)}}
        {...panResponder.panHandlers}>
        {/* Background */}
        <View style={styles.trackBg} />

        {/* Fill */}
        <View style={[styles.trackFill, {width: `${displayFraction * 100}%`}]} />

        {/* Thumb */}
        <Animated.View
          style={[
            styles.thumb,
            {left: `${displayFraction * 100}%`},
            {transform: [{scale: thumbScale}]},
          ]}
        />
      </View>

      {/* Percentage label */}
      <AppText variant="caption" color="secondary" style={styles.pctLabel}>
        {Math.round(displayFraction * 100)}%
      </AppText>
    </View>
  );
};

export default AudioVolumeSlider;

import React, {useRef, useEffect, useMemo, useCallback} from 'react';
import {
  View,
  TouchableOpacity,
  StyleSheet,
  Animated,
  Easing,
  PanResponder,
} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import FastImage from 'react-native-fast-image';
import {useTheme} from '../../../theme';
import {AppText} from '../../core/AppText/AppText';
import {SvgIcon} from '../../utility/SvgIcon';
import AudioWaveform from '../AudioWaveform/AudioWaveform';
import {MiniProgressBar} from './MiniProgressBar';
import {useMiniPlayer} from './useMiniPlayer';
import {navigate} from '../../../navigation/navigationHelper';

// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const MINI_PLAYER_HEIGHT = 64;
const ARTWORK_SIZE = 40;
// WCAG 2.1 AA minimum touch target: 44├ù44 (was 36├ù36 ΓÇö audit 32.1)
const CONTROL_BUTTON_SIZE = 44;

// Tab bar constants must match FloatingTabBar
const TAB_BAR_HEIGHT = 60;
const TAB_BAR_BOTTOM_MARGIN = 10;
const MINI_PLAYER_GAP = 4;

// Swipe gesture thresholds (32.4)
const SWIPE_DISTANCE = 60;

const formatRemaining = (ms: number): string => {
  const totalSec = Math.max(0, Math.ceil(ms / 1000));
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return `${m}:${s.toString().padStart(2, '0')}`;
};

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export const MiniAudioPlayer: React.FC = () => {
  const {colors, spacing, radius, shadows} = useTheme();
  const insets = useSafeAreaInsets();

  const {isVisible, isPlaying, currentTrack, progress, sleepRemainingMs, sleepTimerActive, handlePlayPause, handleNext, handlePrevious, handleDismiss} =
    useMiniPlayer();

  // ΓöÇΓöÇ Slide animation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const slideAnim = useRef(new Animated.Value(1)).current;

  useEffect(() => {
    if (isVisible) {
      // Start from hidden position, then slide up
      slideAnim.setValue(1);
      Animated.timing(slideAnim, {
        toValue: 0,
        duration: 350,
        easing: Easing.bezier(0.4, 0, 0.2, 1),
        useNativeDriver: true,
      }).start();
    } else {
      Animated.timing(slideAnim, {
        toValue: 1,
        duration: 250,
        useNativeDriver: true,
      }).start();
    }
  }, [isVisible, slideAnim]);

  const translateY = slideAnim.interpolate({
    inputRange: [0, 1],
    outputRange: [0, MINI_PLAYER_HEIGHT + MINI_PLAYER_GAP + 12],
  });

  const animOpacity = slideAnim.interpolate({
    inputRange: [0, 0.5, 1],
    outputRange: [1, 0.5, 0],
  });

  // ΓöÇΓöÇ Tap to open AudioPlayer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const handleOpenPlayer = useCallback(() => {
    if (!currentTrack) return;
    navigate('AudioPlayer', {
      fileUri: currentTrack.uri,
      fileTitle: currentTrack.title,
    });
  }, [currentTrack]);

  // ΓöÇΓöÇ Stop propagation on control buttons ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const handlePrevPress = useCallback(() => {
    handlePrevious();
  }, [handlePrevious]);

  const handleNextPress = useCallback(() => {
    handleNext();
  }, [handleNext]);

  // ΓöÇΓöÇ Swipe gestures: down = dismiss, left/right = next/prev (32.4) ΓöÇΓöÇ
  const panResponder = useMemo(
    () =>
      PanResponder.create({
        onMoveShouldSetPanResponder: (_, g) =>
          Math.abs(g.dy) > 12 || Math.abs(g.dx) > 12,
        onPanResponderRelease: (_, g) => {
          if (Math.abs(g.dy) > SWIPE_DISTANCE && Math.abs(g.dy) > Math.abs(g.dx)) {
            handleDismiss();
          } else if (
            Math.abs(g.dx) > SWIPE_DISTANCE &&
            Math.abs(g.dx) > Math.abs(g.dy)
          ) {
            if (g.dx < 0) {
              handleNext();
            } else {
              handlePrevious();
            }
          }
        },
      }),
    [handleDismiss, handleNext, handlePrevious],
  );

  // ΓöÇΓöÇ Derived values ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const title = currentTrack?.title || '';
  const subtitle = currentTrack?.title || ''; // no separate artist field in PlaylistEntry

  // ΓöÇΓöÇ Styles ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const bottomPosition =
    TAB_BAR_HEIGHT + TAB_BAR_BOTTOM_MARGIN + insets.bottom + MINI_PLAYER_GAP;

  const styles = useMemo(
    () =>
      StyleSheet.create({
        container: {
          position: 'absolute',
          left: spacing.lg,
          right: spacing.lg,
          bottom: bottomPosition,
          height: MINI_PLAYER_HEIGHT,
          borderRadius: radius.md,
          overflow: 'hidden',
          zIndex: 50,
        },
        touchableArea: {
          flex: 1,
          flexDirection: 'row',
          alignItems: 'center',
          paddingLeft: spacing.sm,
          paddingRight: spacing.xs,
        },
        artwork: {
          width: ARTWORK_SIZE,
          height: ARTWORK_SIZE,
          borderRadius: ARTWORK_SIZE / 2,
          alignItems: 'center',
          justifyContent: 'center',
          overflow: 'hidden',
        },
        artworkIcon: {
          width: 20,
          height: 20,
        },
        textContainer: {
          flex: 1,
          marginLeft: spacing.md,
          marginRight: spacing.sm,
        },
        titleText: {
          color: colors.text.primary,
          fontSize: 14,
          fontWeight: '500',
          lineHeight: 18,
        },
        subtitleText: {
          color: colors.text.secondary,
          fontSize: 12,
          lineHeight: 16,
          marginTop: 1,
        },
        controls: {
          flexDirection: 'row',
          alignItems: 'center',
          gap: 2,
        },
        controlButton: {
          width: CONTROL_BUTTON_SIZE,
          height: CONTROL_BUTTON_SIZE,
          alignItems: 'center',
          justifyContent: 'center',
          borderRadius: CONTROL_BUTTON_SIZE / 2,
        },
        playButton: {
          width: CONTROL_BUTTON_SIZE,
          height: CONTROL_BUTTON_SIZE,
          alignItems: 'center',
          justifyContent: 'center',
          borderRadius: CONTROL_BUTTON_SIZE / 2,
          backgroundColor: colors.accent.goldDim,
        },
        sleepBadge: {
          position: 'absolute',
          top: 2,
          right: spacing.sm,
          paddingHorizontal: 8,
          paddingVertical: 1,
          borderRadius: 8,
          backgroundColor: colors.accent.goldWash,
          zIndex: 10,
        },
      }),
    [colors, spacing, radius, bottomPosition],
  );

  if (!isVisible) return null;

  return (
    <Animated.View
      pointerEvents="box-none"
      style={[
        styles.container,
        {
          backgroundColor: colors.background.surfaceDark,
          borderWidth: StyleSheet.hairlineWidth,
          borderColor: colors.border.subtle,
          ...shadows.md,
          transform: [{translateY}],
          opacity: animOpacity,
        },
      ]}
      {...panResponder.panHandlers}>
        {/* Gold progress bar at the very top */}
      <MiniProgressBar progress={progress} />

      {/* Sleep timer badge (32.2) */}
      {sleepTimerActive && sleepRemainingMs > 0 && (
        <View style={styles.sleepBadge}>
          <AppText variant="caption" color="primary">
            Sleep {formatRemaining(sleepRemainingMs)}
          </AppText>
        </View>
      )}

      {/* Tappable area ΓÇö opens the audio player */}
      <TouchableOpacity
        activeOpacity={0.7}
        onPress={handleOpenPlayer}
        style={styles.touchableArea}
        accessibilityRole="button"
        accessibilityLabel={`Open audio player: ${title}`}>
        {/* Album artwork with waveform overlay when playing */}
        <View style={styles.artwork}>
          {currentTrack?.uri ? (
            <FastImage
              source={{
                uri: currentTrack.uri,
                priority: FastImage.priority.high,
                cache: FastImage.cacheControl.immutable,
              }}
              style={StyleSheet.absoluteFill}
              resizeMode={FastImage.resizeMode.cover}
            />
          ) : (
            <View style={[StyleSheet.absoluteFill, {backgroundColor: colors.accent.goldDim, alignItems: 'center', justifyContent: 'center'}]}>
              <SvgIcon
                name="music"
                size={22}
                color={colors.text.tertiary}
                style={styles.artworkIcon}
              />
            </View>
          )}
          {isPlaying && (
            <View style={[StyleSheet.absoluteFill, {alignItems: 'center', justifyContent: 'center', backgroundColor: colors.background.scrim}]}>
              <AudioWaveform isPlaying={true} color={colors.accent.gold} size={20} barWidth={2} barGap={2} />
            </View>
          )}
        </View>

        {/* Title & artist */}
        <View style={styles.textContainer}>
          <AppText
            variant="bodySmall"
            numberOfLines={1}
            ellipsizeMode="tail"
            style={styles.titleText}>
            {title || 'No media playing'}
          </AppText>
          <AppText
            variant="caption"
            numberOfLines={1}
            ellipsizeMode="tail"
            style={styles.subtitleText}>
            {subtitle || 'Tap to open player'}
          </AppText>
        </View>

        {/* Transport controls */}
        <View style={styles.controls}>
          {/* Previous */}
          <TouchableOpacity
            onPress={handlePrevPress}
            style={styles.controlButton}
            accessibilityRole="button"
            accessibilityLabel="Previous track"
            accessibilityHint="Swipe right on the mini player for the same action">
            <SvgIcon name="skipBack" size={20} color={colors.text.secondary} />
          </TouchableOpacity>

          {/* Play/Pause */}
          <TouchableOpacity
            onPress={handlePlayPause}
            style={styles.playButton}
            accessibilityRole="button"
            accessibilityLabel={isPlaying ? 'Pause' : 'Play'}>
            <SvgIcon
              name={isPlaying ? 'pause' : 'play'}
              size={20}
              color={colors.accent.gold}
            />
          </TouchableOpacity>

          {/* Next */}
          <TouchableOpacity
            onPress={handleNextPress}
            style={styles.controlButton}
            accessibilityRole="button"
            accessibilityLabel="Next track"
            accessibilityHint="Swipe left on the mini player for the same action">
            <SvgIcon name="skipForward" size={20} color={colors.text.secondary} />
          </TouchableOpacity>
        </View>
      </TouchableOpacity>
    </Animated.View>
  );
};

export default MiniAudioPlayer;

import React from 'react';
import {
  View,
  FlatList,
  TouchableOpacity,
  StyleSheet,
} from 'react-native';
import {useTheme} from '../../../theme';
import {radius, spacing} from '../../../theme/tokens';
import {AppText} from '../../core/AppText/AppText';

// ΓöÇΓöÇΓöÇ Types ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface Chapter {
  title: string;
  startTime: number; // seconds
  endTime: number;
  /** Optional URI to a thumbnail image for this chapter */
  thumbnail?: string;
}

interface ChapterListProps {
  chapters: Chapter[];
  currentTime: number;
  onSeek: (time: number) => void;
}

// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const ITEM_HEIGHT = 60;

// ΓöÇΓöÇΓöÇ Helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

function formatTime(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  return `${m}:${s.toString().padStart(2, '0')}`;
}

function formatDuration(seconds: number): string {
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  if (h > 0) return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
  return `${m}:${s.toString().padStart(2, '0')}`;
}

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export const ChapterList: React.FC<ChapterListProps> = ({
  chapters,
  currentTime,
  onSeek,
}) => {
  const {colors} = useTheme();

  if (chapters.length === 0) {
    return (
      <View style={styles.empty}>
        <AppText variant="body2" color="tertiary">
          No chapters available
        </AppText>
      </View>
    );
  }

  return (
    <FlatList
      data={chapters}
      keyExtractor={(_, i) => String(i)}
      contentContainerStyle={styles.list}
      showsVerticalScrollIndicator={false}
      getItemLayout={(_data, index) => ({
        length: ITEM_HEIGHT,
        offset: ITEM_HEIGHT * index,
        index,
      })}
      windowSize={5}
      maxToRenderPerBatch={10}
      removeClippedSubviews={true}
      renderItem={({item, index}) => {
        const isActive =
          currentTime >= item.startTime && currentTime < item.endTime;
        return (
          <TouchableOpacity
            activeOpacity={0.7}
            onPress={() => onSeek(item.startTime)}
            style={[
              styles.row,
              {
                backgroundColor: isActive
                  ? colors.accent.goldDim
                  : 'transparent',
                borderColor: colors.border.subtle,
              },
            ]}>
            {/* Thumbnail */}
            <View style={[styles.thumb, {backgroundColor: colors.background.elevated}]}>
              {item.thumbnail ? (
                <View style={styles.thumbPlaceholder} />
              ) : (
                <AppText variant="overline" color="tertiary">
                  {index + 1}
                </AppText>
              )}
            </View>

            {/* Info */}
            <View style={styles.info}>
              <AppText
                variant="body2"
                numberOfLines={1}
                style={isActive ? {color: colors.accent.gold} : undefined}>
                {item.title}
              </AppText>
              <AppText variant="caption" color="tertiary">
                {formatTime(item.startTime)} ΓÇö {formatDuration(item.endTime - item.startTime)}
              </AppText>
            </View>

            {/* Active indicator */}
            {isActive && (
              <View style={[styles.activeDot, {backgroundColor: colors.accent.gold}]} />
            )}
          </TouchableOpacity>
        );
      }}
    />
  );
};

