              <AppText variant="caption" color="tertiary" numberOfLines={1}>
                {track.artist || 'Unknown Artist'}
                {track.album ? `  ┬╖  ${track.album}` : ''}
              </AppText>
            </View>
          </View>
          {onPlayTrack && (
            <SvgIcon name="play" size={16} color={colors.accent.gold} />
          )}
        </TouchableOpacity>
      ))}
    </View>
  );
