export const VideoPlayer: React.FC<VideoPlayerHookData> = (h) => {
  if (h.error) {
    return (
      <View style={[styles.root, h.errorStyles.container]}>
        <View style={h.errorStyles.iconCircle}>
          <AppText style={h.errorStyles.icon}>!</AppText>
