const generateItemId = (): string =>
  `pli_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;

// ΓöÇΓöÇΓöÇ Props ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export interface PlaylistSheetProps {
  visible: boolean;
  onClose: () => void;
  currentItem: {
    fileUri: string;
    title: string;
    duration: number;
    artist?: string;
    album?: string;
  };
}

// ΓöÇΓöÇΓöÇ Kind helpers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const KIND_LABELS: Record<PlaylistKind, string> = {
  AUDIO_ONLY: 'Audio',
  VIDEO_ONLY: 'Video',
  MIXED: 'Mixed',
};

const KIND_OPTIONS: PlaylistKind[] = ['AUDIO_ONLY', 'VIDEO_ONLY', 'MIXED'];

// ΓöÇΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const ITEM_HEIGHT = 60;

// ΓöÇΓöÇΓöÇ Component ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export const PlaylistSheet: React.FC<PlaylistSheetProps> = ({
  visible,
  onClose,
  currentItem,
}) => {
  const {colors} = useTheme();
  const dispatch = useAppDispatch();
  const toast = useToast();
  const haptics = useHaptics();
  const playlists = useAppSelector(selectAllPlaylists);

  // ΓöÇΓöÇ Create-mode state ΓöÇΓöÇ
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState('');
  const [newKind, setNewKind] = useState<PlaylistKind>('MIXED');

  // Reset create mode on close
  useEffect(() => {
    if (!visible) {
      setCreating(false);
      setNewName('');
      setNewKind('MIXED');
    }
  }, [visible]);

  // ΓöÇΓöÇ Check if item is in a playlist ΓöÇΓöÇ
  const itemExistsIn = useCallback(
    (playlist: Playlist): boolean =>
      playlist.items.some(i => i.fileUri === currentItem.fileUri),
    [currentItem.fileUri],
  );

  // ΓöÇΓöÇ Add item to playlist ΓöÇΓöÇ
  const handleAddToPlaylist = useCallback(
    (playlistId: string, playlistName: string) => {
      const newItem: PlaylistItem = {
        id: generateItemId(),
        fileUri: currentItem.fileUri,
        title: currentItem.title,
        duration: currentItem.duration,
        artist: currentItem.artist,
        album: currentItem.album,
        addedAt: new Date().toISOString(),
      };
      dispatch(addItemToPlaylist({playlistId, item: newItem}));
      haptics.medium();
      toast.show(`Added to "${playlistName}"`, 'success');
      // Auto-dismiss after short delay
      setTimeout(onClose, 800);
    },
    [currentItem, dispatch, haptics, toast, onClose],
  );

  // ΓöÇΓöÇ Remove item from playlist ΓöÇΓöÇ
  const handleRemoveFromPlaylist = useCallback(
    (playlist: Playlist) => {
      const existing = playlist.items.find(i => i.fileUri === currentItem.fileUri);
      if (existing) {
        dispatch(
          removeItemFromPlaylist({playlistId: playlist.id, itemId: existing.id}),
        );
        haptics.medium();
        toast.show(`Removed from "${playlist.name}"`, 'info');
        setTimeout(onClose, 800);
      }
    },
    [currentItem.fileUri, dispatch, haptics, toast, onClose],
  );

  // ΓöÇΓöÇ Toggle add/remove ΓöÇΓöÇ
  const handleTogglePlaylist = useCallback(
    (playlist: Playlist) => {
      if (itemExistsIn(playlist)) {
        handleRemoveFromPlaylist(playlist);
      } else {
        handleAddToPlaylist(playlist.id, playlist.name);
      }
    },
    [itemExistsIn, handleRemoveFromPlaylist, handleAddToPlaylist],
  );

  // ΓöÇΓöÇ Create new playlist ΓöÇΓöÇ
  const handleCreatePlaylist = useCallback(() => {
    if (!newName.trim()) return;
    dispatch(createPlaylist({name: newName.trim(), kind: newKind}));
    haptics.light();
    toast.show(`Created "${newName.trim()}"`, 'success');
    setCreating(false);
    setNewName('');
  }, [newName, newKind, dispatch, haptics, toast]);

  // ΓöÇΓöÇ Render playlist row ΓöÇΓöÇ
  const renderPlaylistItem = useCallback(
    ({item}: {item: Playlist}) => {
      const exists = itemExistsIn(item);
      return (
        <TouchableOpacity
          style={[
            styles.playlistRow,
            {borderBottomColor: colors.border.subtle},
          ]}
          onPress={() => handleTogglePlaylist(item)}
          activeOpacity={0.7}
          accessibilityRole="button"
          accessibilityLabel={`${itemExistsIn(item) ? 'Remove from' : 'Add to'} playlist "${item.name}"`}>
          {/* Cover / icon */}
          <View
            style={[
              styles.coverPlaceholder,
              {backgroundColor: colors.background.elevated},
            ]}>
            <SvgIcon
              name="listMusic"
              size={20}
              color={exists ? colors.accent.gold : colors.text.secondary}
            />
          </View>

          {/* Name + badge + count */}
          <View style={styles.playlistInfo}>
            <View style={styles.playlistNameRow}>
              <AppText
                variant="body1"
                color="primary"
                numberOfLines={1}
                style={styles.playlistName}>
                {item.name}
              </AppText>
              <View
                style={[
                  styles.kindBadge,
                  {backgroundColor: colors.accent.goldDim},
                ]}>
                <AppText
                  variant="caption"
                  color="primary"
                  style={{color: colors.accent.gold, fontSize: 10}}>
                  {KIND_LABELS[item.kind]}
                </AppText>
              </View>
            </View>
            <AppText variant="caption" color="secondary">
              {item.items.length} {item.items.length === 1 ? 'item' : 'items'}
            </AppText>
          </View>

          {/* Checkmark if exists */}
          {exists && (
            <View style={styles.checkmark}>
              <AppText style={{color: colors.accent.gold, fontSize: 16}}>
                {'Γ£ô'}
              </AppText>
            </View>
          )}
        </TouchableOpacity>
      );
    },
    [colors, itemExistsIn, handleTogglePlaylist],
  );

  // ΓöÇΓöÇ Key extractor ΓöÇΓöÇ
  const keyExtractor = useCallback((item: Playlist) => item.id, []);

  // ΓöÇΓöÇ List header ΓöÇΓöÇ
  const ListHeader = useMemo(
    () => (
      <View style={styles.listHeader}>
        <AppText variant="h3" color="primary">
          Select a Playlist
        </AppText>
        <AppText variant="caption" color="secondary">
          Choose a playlist to add the current track
        </AppText>
      </View>
    ),
    [],
  );

  // ΓöÇΓöÇ List footer (Create New Playlist) ΓöÇΓöÇ
  const ListFooter = useMemo(
    () => (
      <TouchableOpacity
        style={[styles.createRow, {borderTopColor: colors.border.subtle}]}
        onPress={() => setCreating(true)}
        activeOpacity={0.7}
        accessibilityRole="button"
        accessibilityLabel="Create new playlist">
        <View
          style={[
            styles.addIconCircle,
            {borderColor: colors.accent.gold},
          ]}>
          <AppText style={{color: colors.accent.gold, fontSize: 18, lineHeight: 20}}>
            +
          </AppText>
        </View>
        <AppText variant="body1" color="primary" style={{color: colors.accent.gold}}>
          Create New Playlist
        </AppText>
      </TouchableOpacity>
    ),
    [colors],
  );

  // ΓöÇΓöÇ Empty state ΓöÇΓöÇ
  const EmptyList = useMemo(
    () => (
      <View style={styles.emptyState}>
        <SvgIcon name="listMusic" size={40} color={colors.text.tertiary} />
        <AppText variant="body1" color="secondary" style={styles.emptyText}>
          No playlists yet. Create one to get started.
        </AppText>
      </View>
    ),
    [colors],
  );

  // ΓöÇΓöÇ Create-mode form ΓöÇΓöÇ
  const CreateForm = useMemo(
    () => (
      <KeyboardAwareView style={styles.createForm}>
        <AppText variant="h3" color="primary" style={{marginBottom: spacing.sm}}>
          New Playlist
        </AppText>

        {/* 53.3: AppTextInput for the playlist name field */}
        <AppTextInput
          value={newName}
          onChangeText={setNewName}
          placeholder="Playlist name"
          autoFocus
        />

        {/* Kind selector */}
        <AppText
          variant="caption"
          color="secondary"
          style={{marginTop: spacing.sm, marginBottom: spacing.xs}}>
          Type:
        </AppText>
        <View style={styles.kindRow}>
          {KIND_OPTIONS.map(k => (
            <TouchableOpacity
              key={k}
              style={[
                styles.kindChip,
                {
                  backgroundColor:
                    newKind === k
                      ? colors.accent.goldDim
                      : colors.background.elevated,
                  borderColor:
                    newKind === k
                      ? colors.accent.gold
                      : colors.border.subtle,
                },
              ]}
              onPress={() => setNewKind(k)}
              accessibilityRole="button"
              accessibilityLabel={`${KIND_LABELS[k]} playlist type${newKind === k ? ', selected' : ''}`}>
              <AppText
                variant="caption"
                color="primary"
                style={{
                  color:
                    newKind === k ? colors.accent.gold : colors.text.secondary,
                }}>
                {KIND_LABELS[k]}
              </AppText>
            </TouchableOpacity>
          ))}
        </View>

        {/* Action buttons */}
        <View style={styles.createActions}>
          <TouchableOpacity
            style={[
              styles.createBtn,
              {
                backgroundColor: colors.accent.gold,
                opacity: newName.trim() ? 1 : 0.5,
              },
            ]}
            onPress={handleCreatePlaylist}
            disabled={!newName.trim()}
            accessibilityRole="button"
            accessibilityLabel={newName.trim() ? `Create playlist "${newName.trim()}"` : 'Create playlist'}>
            <AppText
              variant="body1"
              color="primary"
              style={{color: colors.text.inverse}}>
              Create
            </AppText>
          </TouchableOpacity>
          <TouchableOpacity
            style={[styles.cancelBtn]}
            onPress={() => setCreating(false)}
            accessibilityRole="button"
            accessibilityLabel="Cancel creating playlist">
            <AppText variant="body1" color="secondary">
              Cancel
            </AppText>
          </TouchableOpacity>
        </View>
      </KeyboardAwareView>
    ),
    [colors, newName, newKind, handleCreatePlaylist],
  );

  return (
    <BottomSheet
      visible={visible}
      onClose={onClose}
      title="Playlists">
      {creating ? (
        CreateForm
      ) : (
        <FlatList
          data={playlists}
          renderItem={renderPlaylistItem}
          keyExtractor={keyExtractor}
          ListHeaderComponent={ListHeader}
          ListFooterComponent={playlists.length > 0 ? ListFooter : null}
          ListEmptyComponent={EmptyList}
          contentContainerStyle={styles.listContent}
          keyboardShouldPersistTaps="handled"
          getItemLayout={(_data, index) => ({
            length: ITEM_HEIGHT,
            offset: ITEM_HEIGHT * index,
            index,
          })}
          windowSize={5}
          maxToRenderPerBatch={10}
          removeClippedSubviews={true}
        />
      )}
    </BottomSheet>
  );
};

