import React from 'react';
import {
  View,
  TouchableOpacity,
  FlatList,
  RefreshControl,
  StyleSheet,
  Platform,
  Dimensions,
} from 'react-native';
import LinearGradient from 'react-native-linear-gradient';
import {SafeAreaView} from 'react-native-safe-area-context';
import {useTheme} from '../../theme';
import {spacing, radius} from '../../theme/tokens';
import {useNavigation} from '@react-navigation/native';
import {useAnimatedEntrance} from '../../hooks/useAnimatedEntrance';
import {AppText} from '../../components/core/AppText/AppText';
import {SvgIcon} from '../../components/utility/SvgIcon';
import {SearchBar} from '../../components/core/SearchBar/SearchBar';
import {EmptyState} from '../../components/feedback/EmptyState/EmptyState';
import {SimbaStatusBar} from '../../components/StatusBar';
import {useAllVideosScreen} from './useAllVideosScreen';

const {width: SCREEN_WIDTH} = Dimensions.get('window');
const COLUMN_COUNT = 2;
const GAP = 12;
const CARD_WIDTH = (SCREEN_WIDTH - spacing.lg * 2 - GAP) / COLUMN_COUNT;

function formatDuration(sec: number): string {
  if (sec <= 0) return '--:--';
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${s.toString().padStart(2, '0')}`;
}

export const AllVideosScreen: React.FC = () => {
  const {colors} = useTheme();
  const navigation = useNavigation();
  const {
    videoTracks,
    searchQuery,
    setSearchQuery,
    sortMode,
    toggleSort,
    viewMode,
    toggleViewMode,
    filteredTracks,
    handlePlayTrack,
    refreshing,
    handleRefresh,
  } = useAllVideosScreen();

  const {styles: animStyles} = useAnimatedEntrance(
    Math.min(filteredTracks.length, 12),
    {staggerDelay: 50, direction: 'fade', duration: 300},
  );

  const renderGridItem = ({item, index}: {item: typeof videoTracks[number]; index: number}) => (
    <TouchableOpacity
      style={[
        styles.card,
        {backgroundColor: colors.background.elevated, borderColor: colors.border.subtle},
        animStyles[index] || {},
      ]}
      activeOpacity={0.7}
      onPress={() => handlePlayTrack(item.uri, item.title)}>
      <View style={[styles.thumb, {backgroundColor: colors.accent.goldDim}]}>
        <SvgIcon name="video" size={28} color={colors.accent.gold} />
      </View>
      <AppText variant="caption" color="primary" numberOfLines={2} style={styles.cardTitle}>
        {item.title}
      </AppText>
      <AppText variant="caption" color="tertiary" numberOfLines={1} style={styles.cardArtist}>
        {item.artist}
      </AppText>
    </TouchableOpacity>
  );

  const renderListItem = ({item, index}: {item: typeof videoTracks[number]; index: number}) => (
    <TouchableOpacity
      style={[
        styles.listItem,
        {backgroundColor: colors.background.elevated, borderColor: colors.border.subtle},
        animStyles[index] || {},
      ]}
      activeOpacity={0.7}
      onPress={() => handlePlayTrack(item.uri, item.title)}>
      <View style={[styles.listThumb, {backgroundColor: colors.accent.goldDim}]}>
        <SvgIcon name="video" size={20} color={colors.accent.gold} />
      </View>
      <View style={styles.listInfo}>
        <AppText variant="body2" color="primary" numberOfLines={1}>
          {item.title}
        </AppText>
        <AppText variant="caption" color="tertiary" numberOfLines={1}>
          {item.artist || 'Unknown'} ┬╖ {formatDuration(item.duration)}
        </AppText>
      </View>
      <SvgIcon
        name="chevronRight"
        size={16}
        color={colors.text.tertiary}
      />
    </TouchableOpacity>
  );

  return (
    <SafeAreaView style={styles.root} edges={['top']}>
      <SimbaStatusBar variant="home" />
      <LinearGradient
        colors={[colors.background.primary, colors.background.elevated]}
        style={StyleSheet.absoluteFill}
      />

      {/* ΓöÇΓöÇ Header ΓöÇΓöÇ */}
      <View style={styles.header}>
        <TouchableOpacity
          style={[styles.headerBtn, {backgroundColor: colors.background.elevated}]}
          onPress={() => navigation.goBack()}
          activeOpacity={0.7}>
          <SvgIcon name="chevronDown" size={18} color={colors.text.primary} />
        </TouchableOpacity>
        <AppText variant="h2" color="primary" style={{flex: 1}}>
          All Videos
        </AppText>
        <TouchableOpacity
          style={[styles.headerBtn, {backgroundColor: colors.background.elevated}]}
          onPress={toggleViewMode}
          activeOpacity={0.7}>
          <SvgIcon
            name={viewMode === 'grid' ? 'layoutList' : 'layoutGrid'}
            size={18}
            color={colors.text.secondary}
          />
        </TouchableOpacity>
        <TouchableOpacity
          style={[styles.headerBtn, {backgroundColor: colors.background.elevated}]}
          onPress={toggleSort}
          activeOpacity={0.7}>
          <SvgIcon name="list" size={16} color={colors.text.secondary} />
        </TouchableOpacity>
      </View>

      {/* ΓöÇΓöÇ Search Bar ΓöÇΓöÇ */}
      {videoTracks.length > 0 && (
        <View style={styles.searchContainer}>
          <SearchBar
            value={searchQuery}
            onChangeText={setSearchQuery}
            placeholder="Search videos..."
          />
        </View>
      )}

      {/* ΓöÇΓöÇ Sort Label ΓöÇΓöÇ */}
      {videoTracks.length > 0 && (
        <View style={styles.sortLabel}>
          <AppText variant="caption" color="tertiary">
            Sorted by {sortMode === 'title' ? 'title' : 'year'}
            {searchQuery.trim()
              ? ` ┬╖ ${filteredTracks.length} of ${videoTracks.length}`
              : ''}
          </AppText>
        </View>
      )}

      {/* ΓöÇΓöÇ Content ΓöÇΓöÇ */}
      {videoTracks.length === 0 ? (
        <View style={styles.emptyWrapper}>
          <EmptyState
            icon="video"
            title="No Videos Found"
            description="No video files found. Scan your media library to find video tracks."
          />
        </View>
      ) : filteredTracks.length === 0 ? (
        <View style={styles.emptyWrapper}>
          <EmptyState
            icon="search"
            title="No Results"
            description="No videos match your search."
          />
        </View>
      ) : viewMode === 'grid' ? (
        <FlatList
          data={filteredTracks}
          renderItem={renderGridItem}
          keyExtractor={item => item.uri}
          numColumns={COLUMN_COUNT}
          columnWrapperStyle={{gap: GAP}}
          contentContainerStyle={styles.listContent}
          showsVerticalScrollIndicator={false}
          getItemLayout={(_, index) => ({length: 76, offset: 76 * index, index})}
          windowSize={5}
          maxToRenderPerBatch={10}
          removeClippedSubviews={true}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={handleRefresh}
              tintColor={colors.accent.gold}
              colors={[colors.accent.gold]}
            />
          }
        />
      ) : (
        <FlatList
          data={filteredTracks}
          renderItem={renderListItem}
          keyExtractor={item => item.uri}
          contentContainerStyle={styles.listContent}
          showsVerticalScrollIndicator={false}
          getItemLayout={(_, index) => ({length: 76, offset: 76 * index, index})}
          windowSize={5}
          maxToRenderPerBatch={10}
          removeClippedSubviews={true}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={handleRefresh}
              tintColor={colors.accent.gold}
              colors={[colors.accent.gold]}
            />
          }
        />
      )}
    </SafeAreaView>
  );
};

