  // ΓöÇΓöÇ Stagger entrance for sections ΓöÇΓöÇ
  const entrance = useAnimatedEntrance(4, {
    staggerDelay: 80,
    direction: 'up',
    duration: 350,
  });

  // ΓöÇΓöÇ Parallax scroll handler ΓöÇΓöÇ
  const onScroll = useMemo(
    () =>
      Animated.event(
        [{nativeEvent: {contentOffset: {y: scrollY}}}],
        {useNativeDriver: true},
      ),
    [scrollY],
  );

  // ΓöÇΓöÇ Track row renderer for remaining tracks ΓöÇΓöÇ
  const renderRemainingTrack = useCallback(
    (track: typeof allTracks[number], idx: number) => {
      const isActive = isCurrentTrack(track.uri);
      const isTrackPlaying = isActive && isPlaying;

      return (
        <TouchableOpacity
          key={track.uri}
          style={[
            styles.remainingTrackRow,
            {
              backgroundColor: isActive
                ? colors.accent.goldFaint
