            },
          ]}
          activeOpacity={0.6}
          onPress={() =>
            handlers.playTrack({
              uri: track.uri,
              title: track.title,
              duration: track.duration,
            })
          }>
          {/* Number or playing indicator */}
          <View style={styles.numCol}>
            {isTrackPlaying ? (
              <AudioWaveform isPlaying={true} color={colors.accent.gold} size={16} barWidth={2} barGap={2} />
            ) : (
              <AppText variant="caption" color="tertiary">
                {idx + 6}
              </AppText>
            )}
          </View>

          {/* Track info */}
          <View style={styles.remainingTrackInfo}>
            <AppText
              variant="body2"
              color={isActive ? 'accent' : 'primary'}
              numberOfLines={1}>
              {track.title}
            </AppText>
            <AppText variant="caption" color="tertiary" numberOfLines={1}>
              {track.album}
            </AppText>
          </View>

          {/* Duration */}
          <AppText variant="caption" color="tertiary" style={styles.remainingDuration}>
            {formatDuration(track.duration)}
          </AppText>
        </TouchableOpacity>
      );
    },
    [isCurrentTrack, isPlaying, handlers, colors],
  );

  // ΓöÇΓöÇ Styles ΓöÇΓöÇ
