          borderRadius: BACK_BTN_SIZE / 2,
          backgroundColor: colors.background.glass,
          alignItems: 'center',
          justifyContent: 'center',
        },
        backBtnElevated: {
          backgroundColor: colors.background.elevated,
        },
        topSectionDivider: {
          height: 1,
          backgroundColor: colors.border.subtle,
          marginHorizontal: spacing.lg,
          marginTop: spacing.lg,
        },
        bottomDivider: {
          height: 1,
          backgroundColor: colors.border.subtle,
          marginHorizontal: spacing.lg,
          marginTop: spacing.md,
        },
      }),
    [colors],
  );

  return (
    <SafeAreaView style={styles.root} edges={['top']}>
      <SimbaStatusBar variant="home" />

      {/* Background gradient */}
      <LinearGradient
        colors={
          isDark
            ? [colors.background.primary, colors.background.elevated]
            : [colors.background.primary, colors.background.elevated]
        }
        style={StyleSheet.absoluteFill}
      />

      {/* ΓöÇΓöÇ Back button (fixed, overlaid) ΓöÇΓöÇ */}
      <View style={[styles.backBtnContainer, {top: insets.top + 8}]}>
        <TouchableOpacity
          style={dynamicStyles.backBtn}
          onPress={handlers.goBack}
          activeOpacity={0.7}>
          <SvgIcon name="chevronDown" size={18} color={colors.text.primary} />
        </TouchableOpacity>
      </View>

      {/* ΓöÇΓöÇ Main scrollable content ΓöÇΓöÇ */}
      <Animated.ScrollView
        showsVerticalScrollIndicator={false}
        scrollEventThrottle={16}
        onScroll={onScroll}
        contentContainerStyle={[
          styles.scrollContent,
          {paddingBottom: insets.bottom + 104},
        ]}>
        {/* ΓöÇΓöÇ Artist Header (parallax) ΓöÇΓöÇ */}
        <ArtistHeader
          artistName={artistName}
          albumCount={stats.albumCount}
          trackCount={stats.trackCount}
