        {/* ΓöÇΓöÇ Empty state ΓöÇΓöÇ */}
        {allTracks.length === 0 && (
          <View style={styles.emptyState}>
            <AppText variant="body2" color="tertiary" style={styles.emptyText}>
              No tracks found for this artist.
            </AppText>
