import React, {useMemo} from 'react';
import {View, StyleSheet, Animated} from 'react-native';
import LinearGradient from 'react-native-linear-gradient';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {useTheme} from '../../../theme';
import {AppText} from '../../../components/core/AppText/AppText';

interface ArtistHeaderProps {
  artistName: string;
  albumCount: number;
  trackCount: number;
  /** Animated scroll value for parallax effect (0 = normal) */
  scrollY?: Animated.Value;
  /** Total height of the parallax region */
  parallaxHeight?: number;
}

const HEADER_HEIGHT = 280;
const AVATAR_SIZE = 88;

export const ArtistHeader: React.FC<ArtistHeaderProps> = ({
  artistName,
  albumCount,
  trackCount,
  scrollY,
  parallaxHeight = HEADER_HEIGHT,
}) => {
  const {colors, isDark} = useTheme();
  const insets = useSafeAreaInsets();

  const initials = useMemo(
    () => artistName.charAt(0).toUpperCase(),
    [artistName],
  );

  // Parallax transforms
  const headerTranslate = useMemo(() => {
    if (!scrollY) return {transform: []};
    return {
      transform: [
        {
          translateY: scrollY.interpolate({
            inputRange: [-parallaxHeight, 0, parallaxHeight],
            outputRange: [parallaxHeight * 0.3, 0, -parallaxHeight * 0.15],
            extrapolate: 'clamp',
          }),
        },
        {
          scale: scrollY.interpolate({
            inputRange: [-parallaxHeight, 0, parallaxHeight],
            outputRange: [1.3, 1, 0.95],
            extrapolate: 'clamp',
          }),
        },
      ],
    };
  }, [scrollY, parallaxHeight]);

  const contentOpacity = useMemo(() => {
    if (!scrollY) return 1;
    return scrollY.interpolate({
      inputRange: [0, parallaxHeight * 0.6],
      outputRange: [1, 0],
      extrapolate: 'clamp',
    });
  }, [scrollY, parallaxHeight]);

  const backdropColors = useMemo(
    () =>
      isDark
        ? [colors.background.scrimOpaque, colors.background.primary, colors.background.elevated]
        : [colors.background.warm, colors.background.primary, colors.background.elevated],
    [isDark, colors],
  );

  return (
    <Animated.View style={[styles.container, headerTranslate]}>
      {/* Gradient backdrop */}
      <LinearGradient
        colors={backdropColors}
        locations={[0, 0.5, 1]}
        style={[styles.gradient, {height: parallaxHeight}]}
        pointerEvents="none"
      />

      {/* Warm glow */}
      <View
        style={[
          styles.glow,
          {
            backgroundColor: colors.accent.gold,
            opacity: isDark ? 0.2 : 0.1,
          },
        ]}
        pointerEvents="none"
      />

      {/* Content */}
      <Animated.View
        style={[
          styles.content,
          {paddingTop: insets.top + 16},
          {opacity: contentOpacity},
        ]}>
        {/* Initials avatar */}
        <LinearGradient
          colors={[colors.accent.gold, colors.accent.goldDim]}
          style={styles.avatar}
          start={{x: 0, y: 0}}
          end={{x: 1, y: 1}}>
          <AppText
            variant="h1"
            style={[styles.initials, {color: colors.text.primary}]}>
            {initials}
          </AppText>
        </LinearGradient>

        {/* Artist name */}
        <AppText
          variant="display"
          color="primary"
          style={styles.name}
