// ΓöÇΓöÇ Constants ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const ITEM_HEIGHT = 76;
const MEDIA_EXTENSIONS = new Set([
  '.mp4', '.mkv', '.avi', '.mov', '.wmv', '.flv', '.webm', '.m4v', '.3gp',
  '.mp3', '.flac', '.wav', '.aac', '.ogg', '.wma', '.m4a', '.opus',
]);

function isMediaFile(name: string): boolean {
  const ext = name.slice(name.lastIndexOf('.')).toLowerCase();
  return MEDIA_EXTENSIONS.has(ext);
}

// ΓöÇΓöÇ Screen ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

type Props = FolderBrowserScreenProps;

interface DirItem {
  name: string;
  path: string;
  isDirectory: boolean;
  size: number;
}

export const FolderBrowserScreen: React.FC<Props> = ({navigation, route}) => {
  const {colors} = useTheme();
  const insets = useSafeAreaInsets();
  const dispatch = useAppDispatch();

  // Initialize breadcrumbs from initialPath param
  const initialPath = route.params?.initialPath ?? '';
  // When opened from PlaylistDetail "Add", pre-target a playlist so the
  // batch action adds directly to it (no picker).
  const targetPlaylistId = route.params?.targetPlaylistId;
  const initialCrumbs = useMemo(() => {
    if (!initialPath) return [];
    return initialPath.split('/').filter(Boolean);
  }, [initialPath]);

  const [breadcrumbs, setBreadcrumbs] = useState<string[]>(initialCrumbs);
  const [items, setItems] = useState<DirItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [refreshing, setRefreshing] = useState(false);

  // ΓöÇΓöÇ Multi-select state ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const [isSelecting, setIsSelecting] = useState(false);
  const [selectedFileNames, setSelectedFileNames] = useState<Set<string>>(
    new Set(),
  );
  const [showPlaylistPicker, setShowPlaylistPicker] = useState(false);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const toast = useToast();

  // ΓöÇΓöÇ Build full path from breadcrumbs ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const currentPath = useMemo(() => {
    if (breadcrumbs.length === 0) return RNFS.ExternalStorageDirectoryPath || '/storage/emulated/0';
    // If initialPath was absolute, reconstruct it
    if (initialPath.startsWith('/')) {
      return '/' + breadcrumbs.join('/');
    }
    return breadcrumbs.join('/');
  }, [breadcrumbs, initialPath]);

  // ΓöÇΓöÇ Read directory contents ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const readDirectory = useCallback(async (path: string) => {
    try {
      setLoading(true);
      setError(null);
      const entries = await RNFS.readDir(path);
      const filtered = entries
        .filter(e => e.isDirectory() || isMediaFile(e.name))
        .map(e => ({
          name: e.name,
          path: e.path,
          isDirectory: e.isDirectory(),
          size: Number(e.size),
        }))
        // Sort: folders first, then by name
        .sort((a, b) => {
          if (a.isDirectory !== b.isDirectory) {
            return a.isDirectory ? -1 : 1;
          }
          return a.name.localeCompare(b.name);
        });
      setItems(filtered);
    } catch (err: any) {
      logger.warn('FolderBrowser readDir error:', err);
      setError(err.message || 'Unable to read directory');
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, []);

  // ΓöÇΓöÇ Effect: read directory when path changes ΓöÇΓöÇ
  useEffect(() => {
    readDirectory(currentPath);
  }, [currentPath, readDirectory]);

  // ΓöÇΓöÇ Auto-enter selection mode when opened to add to a target playlist ΓöÇΓöÇ
  useEffect(() => {
    if (targetPlaylistId) {
      setIsSelecting(true);
    }
  }, [targetPlaylistId]);

  // ΓöÇΓöÇ Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const handleEnterFolder = useCallback((folderPath: string) => {
    // Extract folder name from the full path for breadcrumbs
    const folderName = folderPath.split('/').pop() || folderPath;
    setBreadcrumbs(prev => [...prev, folderName]);
  }, []);

  const handleBreadcrumbPress = useCallback((index: number) => {
    if (index < 0) {
      // Going back to root: use initial root
      setBreadcrumbs([]);
    } else {
      setBreadcrumbs(prev => prev.slice(0, index));
    }
  }, []);

  const handleFilePress = useCallback(
    (filePath: string, fileName: string) => {
      if (isSelecting) {
        setSelectedFileNames(prev => {
          const next = new Set(prev);
          if (next.has(fileName)) {
            next.delete(fileName);
          } else {
            next.add(fileName);
          }
          return next;
        });
        return;
      }
      navigation.navigate(
        isVideoFile(fileName) ? 'VideoPlayer' : 'AudioPlayer',
        {
          fileUri: `file://${filePath}`,
          fileTitle: fileName,
        },
      );
    },
    [navigation, isSelecting],
  );

  const handleRefresh = useCallback(async () => {
    setRefreshing(true);
    await readDirectory(currentPath);
    setRefreshing(false);
  }, [currentPath, readDirectory]);

  // ΓöÇΓöÇ Multi-select handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const handleToggleSelect = useCallback(() => {
    setIsSelecting(prev => {
      if (prev) {
        setSelectedFileNames(new Set());
      }
      return !prev;
    });
  }, []);

  const handleToggleFileSelection = useCallback((fileName: string) => {
    setSelectedFileNames(prev => {
      const next = new Set(prev);
      if (next.has(fileName)) {
        next.delete(fileName);
      } else {
        next.add(fileName);
      }
      return next;
    });
  }, []);

  const handleFileLongPress = useCallback(
    (fileName: string) => {
      if (!isSelecting) {
        setIsSelecting(true);
        setSelectedFileNames(new Set([fileName]));
      } else {
        handleToggleFileSelection(fileName);
      }
    },
    [isSelecting, handleToggleFileSelection],
  );

  const playlistNameMap = useAppSelector(state => {
    const map: Record<string, string> = {};
    for (const pl of state.playlists.playlists) {
      map[pl.id] = pl.name;
    }
    return map;
  });

  const handleBatchAddConfirm = useCallback(
    (playlistId: string) => {
      const selectedItems: PlaylistItem[] = items
        .filter(i => !i.isDirectory && selectedFileNames.has(i.name))
        .map(file => ({
          id: `${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
          fileUri: `file://${file.path}`,
          title: file.name,
          duration: 0,
          addedAt: new Date().toISOString(),
        }));

      selectedItems.forEach(item => {
        dispatch(addItemToPlaylist({playlistId, item}));
      });

      const plName = playlistNameMap[playlistId] ?? 'Playlist';
      toast.show(
        `Added ${selectedItems.length} items to ${plName}`,
        'success',
      );
      setIsSelecting(false);
      setSelectedFileNames(new Set());
      // Targeted flow (opened from PlaylistDetail "Add"): return to it.
      if (targetPlaylistId) {
        navigation.goBack();
      }
    },
    [items, selectedFileNames, toast, playlistNameMap, dispatch, targetPlaylistId, navigation],
  );

  const handleBatchAddToPlaylist = useCallback(() => {
    if (targetPlaylistId) {
      // Opened from a playlist's "Add" button ΓÇö add directly to it.
      handleBatchAddConfirm(targetPlaylistId);
    } else {
      setShowPlaylistPicker(true);
    }
  }, [targetPlaylistId, handleBatchAddConfirm]);

  const handleCreateNewFromBatch = useCallback(() => {
    setShowPlaylistPicker(false);
    setTimeout(() => setShowCreateModal(true), 350);
  }, []);

  const handleCreatePlaylistFromBatch = useCallback(
    (name: string, kind: PlaylistKind) => {
      setShowCreateModal(false);
      const result = dispatch(createPlaylist({name, kind}));
      const playlistId = (result as {payload: Playlist}).payload.id;

      const selectedItems: PlaylistItem[] = items
        .filter(i => !i.isDirectory && selectedFileNames.has(i.name))
        .map(file => ({
          id: `${Date.now()}_${Math.random().toString(36).slice(2, 9)}`,
          fileUri: `file://${file.path}`,
          title: file.name,
          duration: 0,
          addedAt: new Date().toISOString(),
        }));

      selectedItems.forEach(item => {
        dispatch(addItemToPlaylist({playlistId, item}));
      });
      toast.show(
        `Added ${selectedItems.length} items to "${name}"`,
        'success',
      );
      setIsSelecting(false);
      setSelectedFileNames(new Set());
    },
    [items, selectedFileNames, toast, dispatch],
  );

  // ΓöÇΓöÇ Styles ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

  const styles = useMemo(
    () =>
      StyleSheet.create({
        root: {flex: 1},
        breadcrumbRow: {
          flexDirection: 'row',
          alignItems: 'center',
          paddingHorizontal: 20,
          paddingVertical: 8,
          borderBottomWidth: StyleSheet.hairlineWidth,
          borderBottomColor: colors.border.subtle,
          flexWrap: 'wrap',
        },
        breadcrumbItem: {
          flexDirection: 'row',
          alignItems: 'center',
        },
        separator: {
          marginHorizontal: 6,
          color: colors.text.tertiary,
        },
        listContent: {
          paddingHorizontal: 20,
          paddingBottom: insets.bottom + 20,
          flexGrow: 1,
        },
        listEmptyContent: {
          flexGrow: 1,
          justifyContent: 'center',
          alignItems: 'center',
          paddingHorizontal: 20,
        },
        itemRow: {
          flexDirection: 'row',
          alignItems: 'center',
          paddingVertical: 14,
          borderBottomWidth: StyleSheet.hairlineWidth,
          borderBottomColor: colors.border.subtle,
        },
        iconContainer: {
          width: 32,
          alignItems: 'center',
          marginRight: 12,
        },
        emptyContainer: {
          alignItems: 'center',
        },
        emptyTitle: {
          marginTop: 12,
          textAlign: 'center',
        },
        emptySubtitle: {
          marginTop: 6,
          textAlign: 'center',
        },
        centerContent: {
          flexGrow: 1,
          justifyContent: 'center',
          alignItems: 'center',
        },
        errorText: {
          marginTop: 12,
          textAlign: 'center',
          paddingHorizontal: 20,
        },
        // ΓöÇΓöÇ Multi-select ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
        checkbox: {
          width: 24,
          height: 24,
          borderRadius: 12,
          borderWidth: 2,
          alignItems: 'center',
          justifyContent: 'center',
          marginRight: 12,
        },
        checkboxChecked: {
          backgroundColor: colors.accent.gold,
          borderColor: colors.accent.gold,
        },
        checkboxUnchecked: {
          borderColor: colors.border.subtle,
        },
        checkmark: {
          color: colors.text.primary,
          fontSize: 14,
          fontWeight: '700',
          lineHeight: 16,
        },
        batchBar: {
          position: 'absolute',
          left: 20,
          right: 20,
          bottom: insets.bottom + 16,
          backgroundColor: colors.background.elevated,
          borderRadius: 16,
          paddingVertical: 14,
          paddingHorizontal: 20,
          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'center',
          elevation: 8,
          shadowOffset: {width: 0, height: 4},
          shadowOpacity: 0.35,
          shadowRadius: 12,
        },
        batchBarText: {
          fontSize: 16,
          fontWeight: '600',
        },
      }),
    [colors, insets],
  );

  const renderItem = useCallback(
    ({item}: {item: DirItem}) => {
      const isFolder = item.isDirectory;
      const isChecked = !isFolder && selectedFileNames.has(item.name);
      return (
        <TouchableOpacity
          style={styles.itemRow}
          activeOpacity={0.6}
          onPress={() => {
            if (isFolder) {
              handleEnterFolder(item.path);
            } else {
              handleFilePress(item.path, item.name);
            }
          }}
          onLongPress={() => {
            if (!isFolder) {
              handleFileLongPress(item.name);
            }
          }}>
          {/* Show checkbox in selection mode for files */}
          {isSelecting && !isFolder && (
            <View
              style={[
                styles.checkbox,
                isChecked
                  ? styles.checkboxChecked
                  : styles.checkboxUnchecked,
              ]}>
              {isChecked && (
                <AppText style={styles.checkmark}>{'\u2713'}</AppText>
              )}
            </View>
          )}
          <View style={styles.iconContainer}>
            <AppText
              variant="body2"
              color={isFolder ? 'accent' : 'secondary'}>
              {isFolder ? '\u25B6' : '\u25C9'}
            </AppText>
          </View>
          <AppText
            variant="body2"
            color={isFolder ? 'primary' : 'secondary'}
            style={{flex: 1}}
            numberOfLines={1}>
            {item.name}
          </AppText>
          {isFolder && (
            <AppText
              variant="caption"
              color="tertiary"
              style={{marginLeft: 8}}>
              folder
            </AppText>
          )}
        </TouchableOpacity>
      );
    },
    [styles, handleEnterFolder, handleFilePress, isSelecting, selectedFileNames, handleFileLongPress],
  );

  const renderBreadcrumbs = () => {
    return (
      <View style={styles.breadcrumbRow}>
        <TouchableOpacity
          onPress={() => handleBreadcrumbPress(-1)}
          activeOpacity={0.6}>
          <AppText
            variant="caption"
            color={breadcrumbs.length === 0 ? 'accent' : 'secondary'}>
            Home
          </AppText>
        </TouchableOpacity>
        {breadcrumbs.map((segment, index) => {
          const isLast = index === breadcrumbs.length - 1;
          return (
            <View key={`${segment}-${index}`} style={styles.breadcrumbItem}>
              <AppText variant="caption" style={styles.separator}>
                /
              </AppText>
              <TouchableOpacity
                onPress={() => handleBreadcrumbPress(index + 1)}
                disabled={isLast}
                activeOpacity={0.6}>
                <AppText
                  variant="caption"
                  color={isLast ? 'accent' : 'secondary'}>
                  {segment}
                </AppText>
              </TouchableOpacity>
            </View>
          );
        })}
      </View>
    );
  };

  const renderEmptyState = () => {
    if (loading) return null;
    if (error) {
      return (
        <View style={styles.centerContent}>
          <AppText variant="h3" color="tertiary" style={styles.errorText}>
            {error}
          </AppText>
          <AppText
            variant="body2"
            color="tertiary"
            style={styles.emptySubtitle}>
            Pull down to retry
          </AppText>
        </View>
      );
    }
    return (
      <View style={styles.emptyContainer}>
        <AppText variant="h3" color="tertiary" style={styles.emptyTitle}>
          This folder is empty
        </AppText>
        <AppText
          variant="body2"
          color="tertiary"
          style={styles.emptySubtitle}>
          No media files or subfolders found.
        </AppText>
      </View>
    );
  };

  return (
    <View style={styles.root}>
      <SimbaStatusBar variant="home" />
      <LinearGradient
        colors={[colors.background.primary, colors.background.primary]}
        style={StyleSheet.absoluteFill}
      />
      <InternalHeader
        title="Folder Browser"
        subtitle={isSelecting ? `${selectedFileNames.size} Selected` : undefined}
        rightAction={{
          label: isSelecting ? 'Cancel' : 'Select',
          onPress: handleToggleSelect,
        }}
      />
      {renderBreadcrumbs()}
      {loading && items.length === 0 ? (
        <View style={styles.centerContent}>
          <ActivityOrb size={48} />
        </View>
      ) : (
        <FlatList
          style={{flex: 1}}
          data={items}
          keyExtractor={item => item.path}
          renderItem={renderItem}
          contentContainerStyle={
            items.length === 0 ? styles.listEmptyContent : styles.listContent
          }
          ListEmptyComponent={renderEmptyState}
          getItemLayout={(_, index) => ({length: ITEM_HEIGHT, offset: ITEM_HEIGHT * index, index})}
          windowSize={5}
          maxToRenderPerBatch={20}
          removeClippedSubviews={true}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={handleRefresh}
              tintColor={colors.accent.gold}
              colors={[colors.accent.gold]}
              progressBackgroundColor={colors.background.primary}
            />
          }
        />
      )}

      {/* ΓöÇΓöÇ Floating batch action bar ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      {isSelecting && selectedFileNames.size > 0 && (
        <TouchableOpacity
          style={styles.batchBar}
          activeOpacity={0.8}
          onPress={handleBatchAddToPlaylist}>
          <AppText
            variant="body2"
            color="primary"
            style={styles.batchBarText}>
            {targetPlaylistId
              ? `Add to ${playlistNameMap[targetPlaylistId] ?? 'Playlist'} (${selectedFileNames.size})`
              : `Add to Playlist (${selectedFileNames.size})`}
          </AppText>
        </TouchableOpacity>
      )}

      {/* ΓöÇΓöÇ Playlist picker context menu ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <PlaylistContextMenu
        item={undefined}
        batchCount={selectedFileNames.size || undefined}
        visible={showPlaylistPicker}
        onClose={() => setShowPlaylistPicker(false)}
        onAddToPlaylist={handleBatchAddConfirm}
        onCreateNew={handleCreateNewFromBatch}
      />

      {/* ΓöÇΓöÇ Create new playlist modal ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
      <PlaylistCreateModal
        visible={showCreateModal}
        onClose={() => setShowCreateModal(false)}
        onCreate={handleCreatePlaylistFromBatch}
      />
    </View>
  );
};

import React, {useCallback, useEffect, useMemo, useRef, useState} from 'react';
import {
  Animated,
  FlatList,
  ScrollView,
  StyleSheet,
  TouchableOpacity,
  View,
} from 'react-native';
import RNFS from 'react-native-fs';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {useNavigation} from '@react-navigation/native';
import {useTheme} from '../../theme';
import {spacing} from '../../theme/tokens';
import type {ColorTokens} from '../../theme/tokens';
import {useAppDispatch, useAppSelector} from '../../store';
import {
  addVideoFolder,
  addAudioFolder,
  setLastScanTimestamp,
} from '../../store/slices/settingsSlice';
import {
  setScanning,
  setTracks,
  addTracks,
  setScanHistory,
  selectAllTracks,
  type ScanHistory,
} from '../../store/slices/mediaSlice';
import {
  scanFoldersIncremental,
  fileEntriesToTracks,
} from '../../services/fileService';
import {AppText} from '../../components/core/AppText/AppText';
import {SvgIcon} from '../../components/utility/SvgIcon';
import {ActivityOrb} from '../../components/feedback/ActivityOrb/ActivityOrb';
import type {FolderLinkingWizardScreenProps} from '../../navigation/types';

type Props = FolderLinkingWizardScreenProps;
type FolderType = 'video' | 'audio' | 'mixed';

const ITEM_HEIGHT = 76;

const STEPS = ['Type', 'Folder', 'Scan', 'Done'];
const STEP_COUNT = 4;

const FOLDER_TYPE_OPTIONS: {type: FolderType; label: string; icon: 'music' | 'video' | 'folder'; desc: string}[] = [
  {type: 'video', label: 'Videos', icon: 'video', desc: 'Movies, shows, clips'},
  {type: 'audio', label: 'Music', icon: 'music', desc: 'Songs, albums, podcasts'},
  {type: 'mixed', label: 'Mixed', icon: 'folder', desc: 'Both video & audio files'},
];

interface DirEntry {
  name: string;
  path: string;
  isDirectory: boolean;
}

export const FolderLinkingWizard: React.FC<Props> = () => {
  const {colors} = useTheme();
  const insets = useSafeAreaInsets();
  const styles = useMemo(() => createStyles(colors), [colors]);
  const nav = useNavigation<any>();
  const dispatch = useAppDispatch();

  const fadeAnim = useRef(new Animated.Value(1)).current;

  const [step, setStep] = useState(0);
  const [folderType, setFolderType] = useState<FolderType | null>(null);
  const [selectedPath, setSelectedPath] = useState<string>('');
  const [browsePath, setBrowsePath] = useState(RNFS.ExternalStorageDirectoryPath || RNFS.DocumentDirectoryPath);
  const [dirContents, setDirContents] = useState<DirEntry[]>([]);
  const [showBrowser, setShowBrowser] = useState(false);
  const [scanProgress, setScanProgress] = useState(0);
  const [scanComplete, setScanComplete] = useState(false);
  const [fileCount, setFileCount] = useState(0);
  const [error, setError] = useState<string | null>(null);
  const existingTracks = useAppSelector(selectAllTracks);
  /** Guards against re-running the scan when tracks/folders change mid-step */
  const scanStartedRef = useRef(false);

  // ΓöÇΓöÇ Progress dots ΓöÇΓöÇ
  const renderProgressDots = () => (
    <View style={styles.progressRow}>
      {STEPS.map((label, i) => (
        <View key={label} style={styles.dotWrapper}>
          <View
            style={[
              styles.dot,
              {
                backgroundColor:
                  i <= step ? colors.accent.gold : colors.border.subtle,
              },
            ]}
          />
          <AppText
            variant="caption"
            style={{
              color: i <= step ? colors.text.primary : colors.text.tertiary,
              marginTop: spacing.xs,
            }}>
            {label}
          </AppText>
        </View>
      ))}
    </View>
  );

  // ΓöÇΓöÇ Step fade transition ΓöÇΓöÇ
  const transitionStep = useCallback(
    (next: number) => {
      Animated.timing(fadeAnim, {
        toValue: 0,
        duration: 120,
        useNativeDriver: true,
      }).start(() => {
        setStep(next);
        fadeAnim.setValue(0);
        Animated.timing(fadeAnim, {
          toValue: 1,
          duration: 200,
          useNativeDriver: true,
        }).start();
      });
    },
    [fadeAnim],
  );

  // ΓöÇΓöÇ Step 0: Folder Type Selection ΓöÇΓöÇ
  const renderTypeSelection = () => (
    <View style={styles.stepContent}>
      <AppText variant="h2" color="primary" style={styles.stepTitle}>
        What kind of media?
      </AppText>
      <AppText variant="body2" color="tertiary" style={styles.stepSubtitle}>
        Select the type of files you want to link
      </AppText>
      {FOLDER_TYPE_OPTIONS.map(opt => (
        <TouchableOpacity
          key={opt.type}
          style={[
            styles.typeCard,
            {
              backgroundColor: colors.background.elevated,
              borderColor:
                folderType === opt.type
                  ? colors.accent.gold
                  : colors.border.subtle,
            },
          ]}
          onPress={() => setFolderType(opt.type)}
          activeOpacity={0.7}
          accessibilityRole="radio"
          accessibilityState={{selected: folderType === opt.type}}>
          <SvgIcon
            name={opt.icon}
            size={28}
            color={
              folderType === opt.type
                ? colors.accent.gold
                : colors.text.secondary
            }
          />
          <View style={styles.typeTextCol}>
            <AppText variant="body2" color="primary">
              {opt.label}
            </AppText>
            <AppText variant="caption" color="tertiary">
              {opt.desc}
            </AppText>
          </View>
          <View
            style={[
              styles.radio,
              {
                borderColor:
                  folderType === opt.type
                    ? colors.accent.gold
                    : colors.border.subtle,
                backgroundColor:
                  folderType === opt.type ? colors.accent.gold : 'transparent',
              },
            ]}>
            {folderType === opt.type && (
              <View style={styles.radioInner} />
            )}
          </View>
        </TouchableOpacity>
      ))}
    </View>
  );

  // ΓöÇΓöÇ Step 1: Folder Picker ΓöÇΓöÇ
  const loadDirContents = useCallback(async (dirPath: string) => {
    setError(null);
    try {
      const items = await RNFS.readDir(dirPath);
      const dirs = items
        .filter(item => item.isDirectory())
        .map(item => ({
          name: item.name,
          path: item.path,
          isDirectory: true,
        }))
        .sort((a, b) => a.name.localeCompare(b.name));
      setDirContents(dirs);
      setBrowsePath(dirPath);
    } catch {
      setError('Unable to read directory. Check permissions.');
      setDirContents([]);
    }
  }, []);

  const handleBrowseDir = useCallback(
    (dirPath: string) => {
      loadDirContents(dirPath);
    },
    [loadDirContents],
  );

  const handleSelectDir = useCallback(
    (dirPath: string) => {
      setSelectedPath(dirPath);
      setShowBrowser(false);
    },
    [],
  );

  const renderFolderPicker = () => (
    <View style={styles.stepContent}>
      <AppText variant="h2" color="primary" style={styles.stepTitle}>
        Choose a folder
      </AppText>
      <AppText variant="body2" color="tertiary" style={styles.stepSubtitle}>
        Select the folder containing your media files
      </AppText>

      {/* Selected path display */}
      <TouchableOpacity
        style={[styles.pathCard, {backgroundColor: colors.background.elevated}]}
        onPress={() => {
          setShowBrowser(true);
          if (!browsePath) setBrowsePath(RNFS.ExternalStorageDirectoryPath || RNFS.DocumentDirectoryPath);
          loadDirContents(browsePath || RNFS.ExternalStorageDirectoryPath || RNFS.DocumentDirectoryPath);
        }}
        activeOpacity={0.7}>
        <SvgIcon name="folder" size={22} color={colors.accent.gold} />
        <View style={styles.pathTextCol}>
          <AppText variant="body2" color="primary" numberOfLines={1}>
            {selectedPath || 'Tap to browse'}
          </AppText>
          {!selectedPath && (
            <AppText variant="caption" color="tertiary">
              No folder selected
            </AppText>
          )}
        </View>
        <SvgIcon name="chevronRight" size={18} color={colors.text.tertiary} />
      </TouchableOpacity>

      {/* Browse modal */}
      {showBrowser && (
        <View
          style={[
            styles.browserContainer,
            {backgroundColor: colors.background.elevated},
          ]}>
          {/* Breadcrumb */}
          <View style={styles.breadcrumbRow}>
            <TouchableOpacity
              onPress={() =>
                handleBrowseDir(
                  RNFS.ExternalStorageDirectoryPath || RNFS.DocumentDirectoryPath,
                )
              }
              activeOpacity={0.7}>
              <AppText variant="caption" color="accent">
                Root
              </AppText>
            </TouchableOpacity>
            <AppText variant="caption" color="tertiary">
              {' '}/{' '}
            </AppText>
            <AppText variant="caption" color="tertiary" numberOfLines={1}>
              {browsePath.split('/').pop() || browsePath}
            </AppText>
          </View>

          {/* Parent directory */}
          {browsePath !==
            (RNFS.ExternalStorageDirectoryPath || RNFS.DocumentDirectoryPath) && (
            <TouchableOpacity
              style={[styles.dirRow, {borderBottomColor: colors.border.subtle}]}
              onPress={() => {
                const parent = browsePath.split('/').slice(0, -1).join('/');
                if (parent) handleBrowseDir(parent);
              }}
              activeOpacity={0.6}>
              <SvgIcon name="folder" size={20} color={colors.text.tertiary} />
              <AppText
                variant="body2"
                color="tertiary"
                style={{marginLeft: spacing.sm}}>
                ..
              </AppText>
            </TouchableOpacity>
          )}

          {/* Error state */}
          {error && (
            <AppText
              variant="caption"
              color="error"
              style={{padding: spacing.sm, textAlign: 'center'}}>
              {error}
            </AppText>
          )}

          {/* Directory listing */}
          <FlatList
            data={dirContents}
            keyExtractor={item => item.path}
            style={styles.dirList}
            getItemLayout={(_, index) => ({length: ITEM_HEIGHT, offset: ITEM_HEIGHT * index, index})}
            windowSize={5}
            maxToRenderPerBatch={10}
            removeClippedSubviews={true}
            renderItem={({item}) => (
              <TouchableOpacity
                style={[
                  styles.dirRow,
                  {borderBottomColor: colors.border.subtle},
                ]}
                onPress={() => handleBrowseDir(item.path)}
                activeOpacity={0.6}>
                <SvgIcon
                  name="folder"
                  size={20}
                  color={colors.text.secondary}
                />
                <AppText
                  variant="body2"
                  color="primary"
                  style={{marginLeft: spacing.sm}}
                  numberOfLines={1}>
                  {item.name}
                </AppText>
              </TouchableOpacity>
            )}
            ListEmptyComponent={
              !error ? (
                <AppText
                  variant="caption"
                  color="tertiary"
                  style={{padding: spacing.lg, textAlign: 'center'}}>
                  No subdirectories found
                </AppText>
              ) : null
            }
          />

          {/* Select this folder */}
          <TouchableOpacity
            style={[
              styles.selectButton,
              {backgroundColor: colors.accent.gold},
            ]}
            onPress={() => handleSelectDir(browsePath)}
            activeOpacity={0.8}>
            <AppText variant="button" color="inverse">
              Select This Folder
            </AppText>
          </TouchableOpacity>
        </View>
      )}
    </View>
  );

  // ΓöÇΓöÇ Step 2: Real folder scan ΓöÇΓöÇ
  useEffect(() => {
    if (step !== 2) {
      scanStartedRef.current = false;
      return;
    }
    if (scanStartedRef.current || !selectedPath) return;
    scanStartedRef.current = true;

    let cancelled = false;
    const doScan = async () => {
      setScanProgress(0);
      setScanComplete(false);
      setError(null);
      dispatch(setScanning(true));

      try {
        const result = await scanFoldersIncremental(
          [selectedPath],
          null, // full scan ΓÇö this folder has never been scanned
          progress => {
            if (cancelled) return true;
            setFileCount(progress.filesFound);
            setScanProgress(progress.percentComplete);
            return cancelled;
          },
        );
        if (cancelled) return;

        // ΓöÇΓöÇ Persist scanned files into the media store ΓöÇΓöÇ
        const scannedTracks = fileEntriesToTracks(result.files);
        const existingUris = new Set(existingTracks.map(t => t.uri));
        const newTracks = scannedTracks.filter(t => !existingUris.has(t.uri));

        if (existingTracks.length === 0) {
          dispatch(setTracks(newTracks));
        } else if (newTracks.length > 0) {
          dispatch(addTracks(newTracks));
        }

        const history: ScanHistory = {
          lastScanTime: result.scanTimestamp,
          filesAdded: newTracks.length,
          filesRemoved: 0,
          errorsCount: result.errorsCount,
          unsupportedCount: result.unsupportedCount,
        };
        dispatch(setScanHistory(history));
        dispatch(setLastScanTimestamp(result.scanTimestamp));

        setFileCount(result.files.length);
        setScanProgress(100);
        setScanComplete(true);
      } catch {
        setError('Scan failed. Please try again.');
        setScanComplete(false);
      } finally {
        dispatch(setScanning(false));
      }
    };

    doScan();

    return () => {
      cancelled = true;
      dispatch(setScanning(false));
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [step, selectedPath]);

  const renderScanning = () => (
    <View style={[styles.stepContent, styles.centerStep]}>
      {scanComplete ? (
        <>
          <View
            style={[styles.checkCircle, {backgroundColor: colors.semantic.success}]}>
            <AppText variant="h2" style={{color: colors.text.bright}}>
              Γ£ô
            </AppText>
          </View>
          <AppText
            variant="h2"
            color="primary"
            style={{marginTop: spacing.lg, textAlign: 'center'}}>
            Scan Complete
          </AppText>
        </>
      ) : (
        <>
          <ActivityOrb size={64} />
          <AppText
            variant="h2"
            color="primary"
            style={{marginTop: spacing.lg, textAlign: 'center'}}>
            Scanning...
          </AppText>
        </>
      )}

      <View style={styles.scanStats}>
        <View style={[styles.statCard, {backgroundColor: colors.background.elevated}]}>
          <AppText variant="h3" color="accent">
            {fileCount}
          </AppText>
          <AppText variant="caption" color="tertiary">
            Files found
          </AppText>
        </View>
        <View style={[styles.statCard, {backgroundColor: colors.background.elevated}]}>
          <AppText variant="h3" color="accent">
            {scanProgress}%
          </AppText>
          <AppText variant="caption" color="tertiary">
            Complete
          </AppText>
        </View>
      </View>

      {/* Progress bar */}
      <View style={[styles.progressBarBg, {backgroundColor: colors.border.subtle}]}>
        <View
          style={[
            styles.progressBarFill,
            {
              width: `${scanProgress}%`,
              backgroundColor: colors.accent.gold,
            },
          ]}
        />
      </View>

      {error ? (
        <AppText
          variant="caption"
          color="error"
          style={{marginTop: spacing.md, textAlign: 'center'}}>
          {error}
        </AppText>
      ) : null}
    </View>
  );

  // ΓöÇΓöÇ Step 3: Success ΓöÇΓöÇ
  const handleGoToLibrary = useCallback(() => {
    if (!folderType || !selectedPath) return;
    if (folderType === 'video' || folderType === 'mixed') {
      dispatch(addVideoFolder(selectedPath));
    }
    if (folderType === 'audio' || folderType === 'mixed') {
      dispatch(addAudioFolder(selectedPath));
    }
    // Jump straight to the Library tab so scanned media is immediately visible
    nav.navigate('MainTabs', {
      screen: 'LibraryTab',
      params: {screen: 'Library'},
    });
  }, [folderType, selectedPath, dispatch, nav]);

  const handleAddAnother = useCallback(() => {
    setSelectedPath('');
    setDirContents([]);
    setFileCount(0);
    setScanProgress(0);
    setScanComplete(false);
    transitionStep(1);
  }, [transitionStep]);

  const renderSuccess = () => (
    <View style={[styles.stepContent, styles.centerStep]}>
      <View
        style={[styles.checkCircleLarge, {backgroundColor: colors.semantic.success}]}>
        <AppText variant="display" style={{color: colors.text.bright, fontSize: 48}}>
          Γ£ô
        </AppText>
      </View>

      <AppText
        variant="h2"
        color="primary"
        style={{marginTop: spacing.xl, textAlign: 'center'}}>
        Folder Linked!
      </AppText>
      <AppText
        variant="body2"
        color="tertiary"
        style={{textAlign: 'center', marginTop: spacing.sm}}>
        {selectedPath}
      </AppText>

      <View style={styles.successStats}>
        <View style={[styles.statCard, {backgroundColor: colors.background.elevated}]}>
          <AppText variant="h3" color="accent">
            {fileCount}
          </AppText>
          <AppText variant="caption" color="tertiary">
            Media files
          </AppText>
        </View>
        <View style={[styles.statCard, {backgroundColor: colors.background.elevated}]}>
          <AppText variant="h3" color="accent">
            {folderType === 'video'
              ? 'Videos'
              : folderType === 'audio'
              ? 'Music'
              : 'Mixed'}
          </AppText>
          <AppText variant="caption" color="tertiary">
            Type
          </AppText>
        </View>
      </View>

      <TouchableOpacity
        style={[styles.primaryButton, {backgroundColor: colors.accent.gold}]}
        onPress={handleGoToLibrary}
        activeOpacity={0.8}>
        <AppText variant="button" color="inverse">
          Go to Library
        </AppText>
      </TouchableOpacity>

      <TouchableOpacity
        style={[styles.secondaryButton, {borderColor: colors.border.subtle}]}
        onPress={handleAddAnother}
        activeOpacity={0.7}>
        <AppText variant="button" color="accent">
          Add Another Folder
        </AppText>
      </TouchableOpacity>
    </View>
  );

  // ΓöÇΓöÇ Navigation ΓöÇΓöÇ
  const handleBack = useCallback(() => {
    if (step === 0) {
      nav.goBack();
    } else if (step === 1 && showBrowser) {
      setShowBrowser(false);
    } else {
      transitionStep(step - 1);
    }
  }, [step, showBrowser, nav, transitionStep]);

  const handleNext = useCallback(() => {
    if (step === 0 && !folderType) return;
    if (step === 1 && !selectedPath) return;
    if (step === 2 && !scanComplete) return;
    if (step < STEP_COUNT - 1) {
      transitionStep(step + 1);
    }
  }, [step, folderType, selectedPath, scanComplete, transitionStep]);

  const canNext = useMemo(() => {
    if (step === 0) return folderType !== null;
    if (step === 1) return selectedPath !== '';
    if (step === 2) return scanComplete;
    return false;
  }, [step, folderType, selectedPath, scanComplete]);

  // ΓöÇΓöÇ Render ΓöÇΓöÇ
  return (
    <View style={[styles.root, {backgroundColor: colors.background.primary}]}>
      {/* Header */}
      <View
        style={[
          styles.header,
          {
            paddingTop: insets.top + spacing.sm,
            borderBottomColor: colors.border.subtle,
          },
        ]}>
        <TouchableOpacity
          onPress={handleBack}
          style={styles.backBtn}
          activeOpacity={0.7}
          accessibilityLabel="Go back">
          <AppText variant="body1" color="secondary" style={{fontSize: 22}}>
            ΓåÉ
          </AppText>
        </TouchableOpacity>
        <AppText variant="h3" color="primary">
          Link Folder
        </AppText>
        <View style={styles.backBtn} />
      </View>

      {/* Progress dots */}
      <View style={styles.progressSection}>{renderProgressDots()}</View>

      {/* Step content */}
      <ScrollView
        style={{flex: 1}}
        contentContainerStyle={{flexGrow: 1}}
        showsVerticalScrollIndicator={false}>
        <Animated.View style={{flex: 1, opacity: fadeAnim}}>
          {step === 0 && renderTypeSelection()}
          {step === 1 && renderFolderPicker()}
          {step === 2 && renderScanning()}
          {step === 3 && renderSuccess()}
        </Animated.View>
      </ScrollView>

      {/* Bottom actions (steps 0-2) */}
      {step < 3 && (
        <View
          style={[
            styles.bottomBar,
            {
              paddingBottom: insets.bottom + spacing.md,
              borderTopColor: colors.border.subtle,
            },
          ]}>
          <TouchableOpacity
            style={[
              styles.nextButton,
              {
                backgroundColor: canNext
                  ? colors.accent.gold
                  : colors.border.subtle,
              },
            ]}
            onPress={handleNext}
            disabled={!canNext}
            activeOpacity={0.8}>
            <AppText
              variant="button"
              style={{
                color: canNext
                  ? colors.text.bright
                  : colors.text.tertiary,
              }}>
              {step === 2 ? 'Continue' : 'Next'}
            </AppText>
          </TouchableOpacity>
        </View>
      )}
    </View>
  );
};

