          flex: 1,
          alignItems: 'center',
          paddingHorizontal: 32,
        },
        // ΓöÇΓöÇ Album art ΓöÇΓöÇ
        artContainer: {
          width: ART_SIZE,
          height: ART_SIZE,
          borderRadius: 12,
          backgroundColor: colors.border.subtle,
          alignItems: 'center',
          justifyContent: 'center',
          marginTop: 24,
          marginBottom: 32,
        },
        artPlaceholder: {
          fontSize: 48,
          color: colors.text.tertiary,
        },
        // ΓöÇΓöÇ Title / Info ΓöÇΓöÇ
        title: {
          marginBottom: 4,
        },
        artist: {
          marginBottom: 40,
        },
        // ΓöÇΓöÇ Seek bar ΓöÇΓöÇ
        seekRow: {
          flexDirection: 'row',
          alignItems: 'center',
          width: '100%',
          paddingHorizontal: 16,
          marginBottom: 24,
        },
        seekTrack: {
          flex: 1,
          height: 24,
          justifyContent: 'center',
        },
        seekTrackBg: {
          height: 4,
          borderRadius: 4,
          backgroundColor: colors.border.subtle,
        },
        seekTrackFill: {
          position: 'absolute',
          left: 0,
          top: 10,
          height: 4,
          borderRadius: 4,
          backgroundColor: colors.accent.gold,
        },
        seekThumb: {
          position: 'absolute',
          width: 14,
          height: 14,
          borderRadius: 7,
          backgroundColor: colors.accent.gold,
          marginLeft: -7,
          top: 5,
        },
        timeRow: {
          flexDirection: 'row',
          justifyContent: 'space-between',
          width: '100%',
          paddingHorizontal: 16,
          marginTop: -16,
          marginBottom: 32,
        },
        // ΓöÇΓöÇ Transport controls ΓöÇΓöÇ
        transportRow: {
          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 24,
          marginBottom: 32,
        },
        transportBtn: {
          width: 48,
          height: 48,
          borderRadius: 24,
          alignItems: 'center',
          justifyContent: 'center',
        },
        playBtn: {
          width: 64,
          height: 64,
          borderRadius: 32,
          backgroundColor: colors.accent.gold,
          alignItems: 'center',
          justifyContent: 'center',
        },
        transportIcon: {
          fontSize: 22,
          color: colors.text.primary,
        },
        playIcon: {
          fontSize: 28,
          color: colors.background.primary,
        },
        // ΓöÇΓöÇ Volume indicator ΓöÇΓöÇ
        volumeRow: {
          flexDirection: 'row',
          alignItems: 'center',
          justifyContent: 'center',
          gap: 8,
          marginBottom: 32,
        },
        volumeIcon: {
          fontSize: 14,
          color: colors.text.secondary,
        },
        volumeLabel: {
          minWidth: 60,
          textAlign: 'center',
        },
        volumeTrack: {
          width: 120,
          height: 4,
          borderRadius: 4,
          backgroundColor: colors.border.subtle,
          overflow: 'hidden',
        },
        volumeFill: {
          height: '100%',
          borderRadius: 4,
          backgroundColor: colors.accent.gold,
        },
        fullPlayerBtn: {
          alignSelf: 'center',
          paddingHorizontal: 24,
          paddingVertical: 10,
          borderRadius: radius.sm,
          marginBottom: 16,
        },
        centerContainer: {
          flex: 1,
          alignItems: 'center',
          justifyContent: 'center',
          paddingHorizontal: spacing.lg,
        },
        retryButton: {
          marginTop: spacing.md,
          paddingVertical: 10,
          paddingHorizontal: 24,
          borderRadius: 10,
          backgroundColor: colors.accent.goldDim,
        },
      }),
    [colors, insets.top],
  );

  const handleEmptyState = useCallback(() => {
    if (!fileUri) {
      return (
        <View style={[styles.scrollContent, {justifyContent: 'center', alignItems: 'center'}]}>
          <AppText variant="h3" color="tertiary" style={{marginBottom: 8}}>
            No Track Playing
          </AppText>
          <AppText variant="body2" color="tertiary" style={{textAlign: 'center', paddingHorizontal: 32}}>
            Open a file from the player or search to start listening.
          </AppText>
        </View>
      );
    }
    return null;
  }, [fileUri, styles]);

  return (
    <View style={styles.root}>
      <SimbaStatusBar variant="home" />

      <LinearGradient
        colors={
          [colors.background.primary, colors.background.primary]
        }
        style={StyleSheet.absoluteFill}
      />

      <InternalHeader title="Now Playing" />

      {isLoading ? (
        <View style={styles.centerContainer}>
          <ActivityOrb size={48} />
        </View>
      ) : error ? (
        <View style={styles.centerContainer}>
          <AppText
            variant="body1"
            color="error"
            style={{textAlign: 'center', marginBottom: spacing.sm}}>
            {error}
          </AppText>
          <TouchableOpacity
            style={styles.retryButton}
            onPress={handleRetry}
            activeOpacity={0.7}
            accessibilityRole="button"
            accessibilityLabel="Retry loading">
            <AppText variant="button" color="accent">
              Retry
            </AppText>
          </TouchableOpacity>
