          {/* Seek bar */}
          <TouchableOpacity
            style={styles.seekRow}
            activeOpacity={1}
            onPress={handleSeek}
            accessibilityRole="adjustable"
            accessibilityLabel={`Seek position, ${Math.round(positionPct * 100)} percent`}>
            <View style={styles.seekTrack} pointerEvents="none">
              <View style={styles.seekTrackBg} />
              <View
