          {/* Time labels */}
          <View style={styles.timeRow}>
            <AppText variant="caption" color="secondary">
              {currentTime}
            </AppText>
            <AppText variant="caption" color="secondary">
              {totalTime}
            </AppText>
          </View>

          {/* Transport controls */}
          <View style={styles.transportRow}>
            <TouchableOpacity
              style={styles.transportBtn}
              onPress={handlePrev}
              accessibilityLabel="Previous track"
              accessibilityRole="button">
              <AppText style={styles.transportIcon}>{'ΓùÇΓùÇ'}</AppText>
            </TouchableOpacity>

            <TouchableOpacity
              style={styles.playBtn}
              onPress={handlePlayPause}
              accessibilityLabel={isPlaying ? 'Pause' : 'Play'}
              accessibilityRole="button">
              <AppText style={styles.playIcon}>
                {isPlaying ? 'ΓÅ╕' : 'Γû╢'}
              </AppText>
            </TouchableOpacity>

            <TouchableOpacity
              style={styles.transportBtn}
              onPress={handleNext}
              accessibilityLabel="Next track"
              accessibilityRole="button">
              <AppText style={styles.transportIcon}>{'Γû╢Γû╢'}</AppText>
            </TouchableOpacity>
          </View>

          {/* Full Player button */}
          <TouchableOpacity
            style={[styles.fullPlayerBtn, {backgroundColor: colors.accent.goldDim}]}
            onPress={handleOpenFullPlayer}
            activeOpacity={0.7}
            accessibilityRole="button"
            accessibilityLabel="Open full player">
            <AppText variant="body2" color="accent">
              Open Full Player
            </AppText>
          </TouchableOpacity>

          {/* Volume indicator */}
          <View style={styles.volumeRow}>
            <AppText style={styles.volumeIcon}>{'≡ƒöê'}</AppText>
            <View style={styles.volumeTrack}>
              <View
                style={[
                  styles.volumeFill,
                  {width: '70%'},
                ]}
              />
            </View>
            <AppText variant="caption" color="secondary" style={styles.volumeLabel}>
