import {SearchBar} from '../../components/core/SearchBar/SearchBar';
import type {PodcastResult} from '../../types/api';

// ΓöÇΓöÇΓöÇ Props ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface PodcastsScreenProps extends RootStackScreenProps<'PodcastsScreen'> {
  onPodcastPress?: (item: PodcastResult) => void;
}

// ΓöÇΓöÇΓöÇ Category Chip ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface CategoryChipProps {
  category: (typeof PODCAST_CATEGORIES)[number];
  isSelected: boolean;
  onPress: (id: number) => void;
}

const CategoryChip: React.FC<CategoryChipProps> = React.memo(
  ({category, isSelected, onPress}) => {
    const {colors} = useTheme();
    return (
      <TouchableOpacity
        activeOpacity={0.8}
        onPress={() => onPress(category.id)}
        style={[
          styles.chip,
          {
            backgroundColor: isSelected
              ? colors.accent.gold
              : colors.background.elevated,
            borderColor: isSelected
              ? colors.accent.gold
              : colors.background.highlight,
          },
        ]}>
        <SvgIcon
          name={category.icon as any}
          size={14}
          color={isSelected ? colors.text.inverse : colors.text.secondary}
        />
        <AppText
          variant="button"
          style={[
            styles.chipText,
            {color: isSelected ? colors.text.inverse : colors.text.secondary},
          ]}>
          {category.name}
        </AppText>
      </TouchableOpacity>
    );
  },
);

// ΓöÇΓöÇΓöÇ Podcast Card ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

interface PodcastCardProps {
  item: PodcastResult;
  onPress: (item: PodcastResult) => void;
}

const PodcastCard: React.FC<PodcastCardProps> = React.memo(
  ({item, onPress}) => {
    const {colors} = useTheme();

    return (
      <TouchableOpacity
        activeOpacity={0.85}
        onPress={() => onPress(item)}
        style={[
          styles.podcastCard,
          {backgroundColor: colors.background.elevated},
        ]}>
        {/* Image / Placeholder */}
        <View
          style={[
            styles.podcastImage,
            {backgroundColor: colors.border.subtle},
          ]}>
          <SvgIcon name="music" size={24} color={colors.accent.goldDim} />
        </View>

        {/* Info column */}
        <View style={styles.podcastInfo}>
          <AppText
            variant="bodySmall"
            numberOfLines={1}
            style={styles.podcastTitle}>
            {item.title}
          </AppText>
          {item.author ? (
            <AppText variant="caption" color="secondary" numberOfLines={1}>
              {item.author}
            </AppText>
          ) : null}
          {item.episodeCount > 0 && (
            <View
              style={[
                styles.episodeBadge,
                {backgroundColor: colors.accent.goldDim},
              ]}>
              <AppText
                variant="caption"
                style={[styles.episodeText, {color: colors.accent.gold}]}>
                {item.episodeCount} ep.
              </AppText>
            </View>
          )}
        </View>

        {/* Arrow */}
        <SvgIcon
          name="chevronRight"
          size={18}
          color={colors.text.tertiary}
        />
      </TouchableOpacity>
    );
  },
);

// ΓöÇΓöÇΓöÇ Screen ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export const PodcastsScreen: React.FC<PodcastsScreenProps> = ({
  navigation: _navigation,
  route,
  onPodcastPress,
}) => {
  const {colors} = useTheme();
  const insets = useSafeAreaInsets();
  const {
    selectedCategory,
    setSelectedCategory,
    results,
    isLoading,
    error,
    searchQuery,
    setSearchQuery,
    isOnline,
    refreshing,
    handleRefresh,
    retry,
    loadMore,
    hasMore,
  } = usePodcastsScreen(route.params?.categoryId);

  const handleCategoryPress = useCallback(
    (id: number) => {
      setSearchQuery('');
      setSelectedCategory(id);
    },
    [setSelectedCategory, setSearchQuery],
  );

  const handlePodcastPress = useCallback(
    (item: PodcastResult) => {
      if (onPodcastPress) {
        onPodcastPress(item);
      }
    },
    [onPodcastPress],
  );

  // Derive the current results key
  const currentKey = useMemo(() => {
    if (searchQuery.trim()) {
      return `search_${searchQuery.trim().toLowerCase()}`;
    }
    return `cat_${selectedCategory}`;
  }, [searchQuery, selectedCategory]);

  const currentResults = results[currentKey] ?? [];
  const isEmpty = currentResults.length === 0 && !isLoading && !error;

  return (
    <View
      style={[
        styles.root,
        {backgroundColor: colors.background.primary, paddingTop: insets.top},
      ]}>
      <SimbaStatusBar variant="home" />
      <InternalHeader title="Podcasts" />

      {/* ΓöÇΓöÇ Search Bar (53.3: core SearchBar) ΓöÇΓöÇ */}
      <View style={styles.searchSection}>
        <SearchBar
          value={searchQuery}
          onChangeText={setSearchQuery}
          placeholder="Search podcastsΓÇª"
        />
      </View>

      {/* ΓöÇΓöÇ Category Chips ΓöÇΓöÇ */}
      <View
        style={[
          styles.chipSection,
          {borderBottomColor: colors.border.subtle},
        ]}>
        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          contentContainerStyle={styles.chipScroll}>
          {PODCAST_CATEGORIES.map(cat => (
            <CategoryChip
              key={cat.id}
              category={cat}
              isSelected={selectedCategory === cat.id}
              onPress={handleCategoryPress}
            />
          ))}
        </ScrollView>
      </View>

      {/* ΓöÇΓöÇ Content Area ΓöÇΓöÇ */}
      <View style={styles.contentArea}>
        {isLoading && currentResults.length === 0 && (
          <SkeletonList count={6} hasImage lines={2} />
        )}

        {error && currentResults.length === 0 && (
          <ErrorState
            title={isOnline ? 'Couldn\'t load podcasts' : 'You\'re offline'}
            message={
              isOnline
                ? error
                : 'Connect to the internet, then retry to browse podcasts.'
            }
            onRetry={retry}
            retryLabel="Retry"
          />
        )}

        {isEmpty && !isLoading && (
          <View style={styles.centerState}>
            <SvgIcon
              name="folder"
              size={40}
              color={colors.accent.goldDim}
            />
            <AppText
              variant="body2"
              color="tertiary"
              style={styles.stateText}>
              No podcasts found.
            </AppText>
          </View>
        )}

        {!isLoading && !error && currentResults.length > 0 && (
          <FlatList
            data={currentResults}
            renderItem={({item}) => (
              <PodcastCard item={item} onPress={handlePodcastPress} />
            )}
            keyExtractor={item => String(item.id)}
            contentContainerStyle={styles.listContent}
            showsVerticalScrollIndicator={false}
            ItemSeparatorComponent={() => (
              <View style={styles.separator} />
            )}
            getItemLayout={(_, index) => ({length: 76, offset: 76 * index, index})}
            windowSize={5}
            maxToRenderPerBatch={10}
            removeClippedSubviews={true}
            refreshControl={
              <RefreshControl
                refreshing={refreshing}
                onRefresh={handleRefresh}
                tintColor={colors.accent.gold}
                colors={[colors.accent.gold]}
              />
            }
            onEndReached={hasMore ? loadMore : undefined}
            onEndReachedThreshold={0.4}
            ListFooterComponent={
              hasMore && isLoading ? (
                <View style={styles.footerLoading}>
                  <ActivityOrb size={20} />
                  <AppText variant="caption" color="tertiary">
                    Loading moreΓÇª
                  </AppText>
                </View>
              ) : null
            }
          />
        )}
      </View>
    </View>
  );
};

// ΓöÇΓöÇΓöÇ Styles ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const styles = StyleSheet.create({
  root: {
    flex: 1,
  },
  searchSection: {
    paddingHorizontal: spacing.md,
    paddingTop: spacing.sm,
    paddingBottom: spacing.xs,
  },
  chipSection: {
    paddingVertical: spacing.sm,
    borderBottomWidth: 1,
  },
  chipScroll: {
    paddingHorizontal: spacing.md,
    gap: spacing.sm,
