import React from 'react';
import {View, TouchableOpacity, StyleSheet} from 'react-native';
import {AppText} from '../../../components/core/AppText/AppText';
import {Dialog} from '../../../components/core/Dialog/Dialog';
import type {ColorTokens} from '../../../theme/tokens';

interface SubtitleLanguageDialogProps {
  visible: boolean;
  onClose: () => void;
  /** Current comma-separated language codes, e.g. "eng, jpn" */
  preferredLanguages: string;
  onSelect: (codes: string) => void;
  colors: ColorTokens;
}

const LANGUAGES: Array<{code: string; label: string}> = [
  {code: 'und', label: 'Default (auto)'},
  {code: 'eng', label: 'English'},
  {code: 'spa', label: 'Spanish'},
  {code: 'fre', label: 'French'},
  {code: 'ger', label: 'German'},
  {code: 'ita', label: 'Italian'},
  {code: 'por', label: 'Portuguese'},
  {code: 'jpn', label: 'Japanese'},
  {code: 'kor', label: 'Korean'},
  {code: 'chi', label: 'Chinese'},
  {code: 'ara', label: 'Arabic'},
  {code: 'rus', label: 'Russian'},
  {code: 'hin', label: 'Hindi'},
  {code: 'tur', label: 'Turkish'},
  {code: 'dut', label: 'Dutch'},
  {code: 'pol', label: 'Polish'},
  {code: 'swe', label: 'Swedish'},
  {code: 'dan', label: 'Danish'},
  {code: 'nor', label: 'Norwegian'},
  {code: 'fin', label: 'Finnish'},
  {code: 'gre', label: 'Greek'},
  {code: 'ind', label: 'Indonesian'},
  {code: 'tha', label: 'Thai'},
  {code: 'vie', label: 'Vietnamese'},
];

export const SubtitleLanguageDialog: React.FC<SubtitleLanguageDialogProps> = ({
  visible,
  onClose,
  preferredLanguages,
  onSelect,
  colors,
}) => {
  const currentCodes = preferredLanguages
    .split(',')
    .map(c => c.trim())
    .filter(Boolean);

  const toggle = (code: string) => {
    const has = currentCodes.includes(code);
    let next: string[];
    if (code === 'und') {
      next = has ? [] : ['und'];
    } else {
      next = currentCodes.filter(c => c !== 'und');
      next = has ? next.filter(c => c !== code) : [...next, code];
    }
    onSelect(next.length > 0 ? next.join(', ') : 'und');
  };

  return (
    <Dialog
      visible={visible}
      onClose={onClose}
      title="Subtitle Language"
      message="Pick preferred subtitle languages (mpv slang). Tap to toggle.">
      <View style={styles.grid}>
        {LANGUAGES.map(lang => {
          const isSelected = currentCodes.includes(lang.code);
          return (
            <TouchableOpacity
              key={lang.code}
              style={[
                styles.chip,
                {
                  backgroundColor: isSelected
                    ? colors.accent.goldDim
                    : 'transparent',
                  borderColor: isSelected
                    ? colors.accent.gold
                    : colors.border.emphasis,
                },
              ]}
              activeOpacity={0.7}
              accessibilityRole="button"
              accessibilityState={{selected: isSelected}}
              accessibilityLabel={`${lang.label} subtitles`}
              onPress={() => toggle(lang.code)}>
              <AppText
                variant="caption"
                color={isSelected ? 'accent' : 'secondary'}>
                {lang.label}
              </AppText>
            </TouchableOpacity>
          );
        })}
      </View>
    </Dialog>
  );
};

const styles = StyleSheet.create({
  grid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
    marginTop: 4,
    maxHeight: 320,
  },
  chip: {
    paddingVertical: 8,
    paddingHorizontal: 12,
    borderRadius: 8,
    borderWidth: 1,
  },
});

import React from 'react';
import {View, TouchableOpacity, StyleSheet} from 'react-native';
import {AppText} from '../../../components/core/AppText/AppText';
import {Dialog} from '../../../components/core/Dialog/Dialog';
import {SUBTITLE_COLOR_PRESETS} from '../../../constants/subtitleColors';
import type {ColorTokens} from '../../../theme/tokens';

interface SubtitleStyleDialogProps {
  visible: boolean;
  onClose: () => void;
  fontSize: number;
  textColor: string;
  bgOpacity: number;
  onFontSize: (px: number) => void;
  onTextColor: (color: string) => void;
  onBgOpacity: (opacity: number) => void;
  colors: ColorTokens;
}

const FONT_SIZES: Array<{px: number; label: string}> = [
  {px: 14, label: 'Small'},
  {px: 18, label: 'Medium'},
  {px: 24, label: 'Large'},
  {px: 32, label: 'XL'},
];

// 55.8: subtitle color palette is DATA (mpv sub-color values), shared via constants
const TEXT_COLORS: Array<{hex: string; label: string}> = SUBTITLE_COLOR_PRESETS;

const BG_OPACITIES: Array<{value: number; label: string}> = [
  {value: 0, label: 'None'},
  {value: 0.3, label: 'Light'},
  {value: 0.5, label: 'Medium'},
  {value: 0.8, label: 'Heavy'},
  {value: 1, label: 'Full'},
];

export const SubtitleStyleDialog: React.FC<SubtitleStyleDialogProps> = ({
  visible,
  onClose,
  fontSize,
  textColor,
  bgOpacity,
  onFontSize,
  onTextColor,
  onBgOpacity,
  colors,
}) => {
  return (
    <Dialog
      visible={visible}
      onClose={onClose}
      title="Subtitle Style"
      message="Changes apply to video playback immediately.">
      {/* Font size */}
      <AppText variant="overline" color="secondary" style={styles.sectionLabel}>
        Font Size
      </AppText>
      <View style={styles.row}>
        {FONT_SIZES.map(opt => {
          const isSelected = fontSize === opt.px;
          return (
            <TouchableOpacity
              key={opt.px}
              style={[
                styles.chip,
                {
                  backgroundColor: isSelected
                    ? colors.accent.goldDim
                    : 'transparent',
                  borderColor: isSelected
                    ? colors.accent.gold
                    : colors.border.emphasis,
                },
              ]}
              activeOpacity={0.7}
              accessibilityRole="button"
              accessibilityState={{selected: isSelected}}
              onPress={() => onFontSize(opt.px)}>
              <AppText
                variant="caption"
                color={isSelected ? 'accent' : 'secondary'}>
                {opt.label}
              </AppText>
            </TouchableOpacity>
          );
        })}
      </View>

      {/* Text color */}
      <AppText variant="overline" color="secondary" style={styles.sectionLabel}>
        Text Color
      </AppText>
      <View style={styles.row}>
        {TEXT_COLORS.map(opt => {
          const isSelected = textColor === opt.hex;
          return (
            <TouchableOpacity
              key={opt.hex}
              style={[
                styles.swatch,
                {
                  backgroundColor: opt.hex,
                  borderColor: isSelected
                    ? colors.accent.gold
                    : colors.border.emphasis,
                },
              ]}
              activeOpacity={0.7}
              accessibilityRole="button"
              accessibilityState={{selected: isSelected}}
              accessibilityLabel={`${opt.label} subtitle text`}
              onPress={() => onTextColor(opt.hex)}
            />
          );
        })}
      </View>

      {/* Background opacity */}
      <AppText variant="overline" color="secondary" style={styles.sectionLabel}>
        Background Opacity
      </AppText>
      <View style={styles.row}>
        {BG_OPACITIES.map(opt => {
          const isSelected = Math.abs(bgOpacity - opt.value) < 0.01;
          return (
            <TouchableOpacity
              key={opt.label}
              style={[
                styles.chip,
                {
                  backgroundColor: isSelected
                    ? colors.accent.goldDim
                    : 'transparent',
                  borderColor: isSelected
                    ? colors.accent.gold
                    : colors.border.emphasis,
                },
              ]}
              activeOpacity={0.7}
              accessibilityRole="button"
              accessibilityState={{selected: isSelected}}
              onPress={() => onBgOpacity(opt.value)}>
              <AppText
                variant="caption"
                color={isSelected ? 'accent' : 'secondary'}>
                {opt.label}
              </AppText>
            </TouchableOpacity>
          );
        })}
      </View>
    </Dialog>
  );
};

const styles = StyleSheet.create({
  sectionLabel: {
    marginTop: 12,
    marginBottom: 6,
  },
  row: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 8,
  },
  chip: {
    paddingVertical: 8,
    paddingHorizontal: 12,
    borderRadius: 8,
    borderWidth: 1,
  },
  swatch: {
    width: 34,
    height: 34,
    borderRadius: 17,
    borderWidth: 2,
  },
});

import React from 'react';
import {View, TouchableOpacity, StyleSheet} from 'react-native';
import {AppText} from '../../../components/core/AppText/AppText';
import {Dialog} from '../../../components/core/Dialog/Dialog';
import type {ColorTokens} from '../../../theme/tokens';

interface ThemePickerDialogProps {
  visible: boolean;
  onClose: () => void;
  themeMode: 'system' | 'dark' | 'light';
  onSelectTheme: (mode: 'system' | 'dark' | 'light') => void;
  colors: ColorTokens;
}

const THEMES: Array<'system' | 'dark' | 'light'> = ['system', 'dark', 'light'];

export const ThemePickerDialog: React.FC<ThemePickerDialogProps> = ({
  visible,
  onClose,
  themeMode,
  onSelectTheme,
  colors,
}) => {
  return (
    <Dialog
      visible={visible}
      onClose={onClose}
      title="Select Theme"
      message="Choose your preferred appearance">
      <View style={styles.row}>
        {THEMES.map(mode => {
          const isSelected = themeMode === mode;
          return (
            <TouchableOpacity
              key={mode}
              style={[
                styles.btn,
                {
                  backgroundColor: isSelected
                    ? colors.accent.gold
                    : 'transparent',
                  borderWidth: 1,
                  borderColor: isSelected
                    ? colors.accent.gold
                    : colors.border.emphasis,
                },
              ]}
              activeOpacity={0.7}
              onPress={() => {
                onSelectTheme(mode);
                onClose();
              }}>
              <AppText
                variant="button"
                color={isSelected ? 'primary' : 'secondary'}>
                {mode.charAt(0).toUpperCase() + mode.slice(1)}
              </AppText>
            </TouchableOpacity>
          );
        })}
      </View>
    </Dialog>
  );
};

const styles = StyleSheet.create({
  row: {
    flexDirection: 'row',
    gap: 10,
    marginTop: 4,
  },
  btn: {
    flex: 1,
    paddingVertical: 12,
    paddingHorizontal: 8,
    borderRadius: 10,
    alignItems: 'center',
    justifyContent: 'center',
  },
});
